INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chronicles of Mystery: The Scorpio Ritual', 'Uncover the darkest secret of humanity! Young archeologist Sylvie Leroux accidentally stumbles upon an ancient secret. What she doesn''t realize is that her research will put her in deadly peril. Who wants to prevent her from finishing her research? Are mere humans standing in her way, or is it a supernatural power?' FROM games WHERE igdb_id = 16043 ON CONFLICT (game_id, language_code) DO NOTHING;
