INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My First Dollhouse', 'Play along as Emily in this interactive dollhouse game! Help Mom and Dad around the house by setting the table, watering the flowers, taking care of the family pets and much, much more! There are lots of fun things to do in this busy house! * Decorate every room in this fully customizable dollhouse * Fun and easy pick up and play style game * Over 40 mini games to play!' FROM games WHERE igdb_id = 206769 ON CONFLICT (game_id, language_code) DO NOTHING;
