INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Princess and the Frog', 'Experience Tiana''s exciting world set in the jazz-infused era of 1920''s New Orleans with the official The Princess and the Frog video game. Celebrate favorite moments from the movie and take on new challenges with Tiana, as she pursues her dreams in a fun adventure.' FROM games WHERE igdb_id = 17753 ON CONFLICT (game_id, language_code) DO NOTHING;
