INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blue Toad Murder Files: The Mysteries of Little Riddle', 'Blue Toad Murder File: The Mysteries of Little Riddle is a one to four player co-operative episodic download game published by Relentless Software. Set in the sleepy village of Little Riddle, the main aim of the game is to follow clues to find the murderer.' FROM games WHERE igdb_id = 18790 ON CONFLICT (game_id, language_code) DO NOTHING;
