INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Path', 'The Path is a psychological horror art game developed by Tale of Tales originally released for the Microsoft Windows operating system on March 18, 2009 in English and Dutch, and later ported to Mac OS X by TransGaming Technologies. It is inspired by several versions of the fairy tale Little Red Riding Hood, and by folklore tropes and conventions in general, but set in contemporary times. The player can choose to control one of six different sisters, who are sent one-by-one on errands by their mother to see their sick grandmother. The player can choose whether to stay on the path or to wander, where wolves are lying in wait.' FROM games WHERE igdb_id = 10199 ON CONFLICT (game_id, language_code) DO NOTHING;
