INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sunday x Magazine: Nettou! Dream Nine', 'Sunday X Magazine: Nettou! Dream Nine is a Baseball simulator developed by Pawapuro Productions and published in 2009 by Konami for the Nintendo DS. It is a spinoff of the Power Pro-kun Pocket series made to celebrate the 50th anniversary of the Weekly Shōnen Sunday and Weekly Shōnen Magazine manga magazines. Titles include H2, Touch, Strongest! Aoizaka Metropolitan High School Baseball Club", Diamond of Ace, and Cross Game. It also contains characters from other non-baseball themed manga, such as Ghost Sweeper Mikami, Ranma ½, Detective Conan, Hayate the Combat Butler, and Hajime no Ippo.' FROM games WHERE igdb_id = 61451 ON CONFLICT (game_id, language_code) DO NOTHING;
