INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crazy Chicken Tales', 'Prepare for the wildest ride of your life! Join Moorhuhn and his friends on their greatest adventure searching for the Forsaken Castle of lore. Face deadly traps and cunning fiends as you jump, run or ride on the backs of Moorhuhn’s friends through colorful cartoon landscapes of mysterious woods, rocky mountain ranges, treacherous ice plains and gloomy dungeons. Embark on an epic quest for treasure and find the true value of courage and friendship in Crazy Chicken Tales.' FROM games WHERE igdb_id = 10111 ON CONFLICT (game_id, language_code) DO NOTHING;
