INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magnetis', 'Magnetis is all about attraction! Connect the magnets to create electric explosions. Solving this frantic puzzle will require quick thinking and foresight, anticipating connections in order to generate massive chain reactions to win the highest number of points! Team up with your friends in cooperative mode or play against them in battle mode, with up to 4 players competing for the highest score.' FROM games WHERE igdb_id = 16082 ON CONFLICT (game_id, language_code) DO NOTHING;
