INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fling!', 'The latest puzzle-sensation from the makers of Fuzzle has finally arrived after over one year in development! Featuring 10,000s of unique puzzles, such that no two puzzles you encounter are ever the same, and split into 30 levels of increasing difficulty, Fling guarantees you many long hours of puzzling fun! Each puzzle has a single, unique solution, and is solved by simply flinging (pushing) the furballs, and watching them bump each other off the edge of the screen, until only one is left.' FROM games WHERE igdb_id = 343986 ON CONFLICT (game_id, language_code) DO NOTHING;
