INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disgaea Infinite', 'Disgaea Infinite takes the lovable characters and game world of the legendary Disgaea series and throws them into a fresh new "visual novel" game style, offering a thrilling mystery to solve, clues to hunt, and a suspect to track down. You are given full control over the story, including the ability to travel back and forth in time and choosing how characters will act, making for an exciting new experience in the Disgaea universe!' FROM games WHERE igdb_id = 21742 ON CONFLICT (game_id, language_code) DO NOTHING;
