INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('night-at-the-museum-battle-of-the-smithsonian-the-video-game', 5073, '2009-05-05', 40, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2d6m.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/j4rg8tgotvzm7sgwjd2d.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Night at the Museum: Battle of the Smithsonian - The Video Game', 'Get ready for a story so epic it could only unfold in the corridors of the world''s largest museum--the Smithsonian Institution. Museum guard-turned entrepreneur Larry Daley discovers that his favorite exhibits, and some of his best friends, from New York''s Natural History Museum are being shipped off to the archives at the Smithsonian. Larry gets a distress call from the miniature cowboy, Jedediah, reporting that Egyptian ruler Kahmunrah and a trio of heinous henchmen--namely Ivan the Terrible, Napoleon and Al Capone--are plotting to take over the museum, then the world. Speeding to the nation''s capitol, Larry is clearly in over his head. But with some impressive new pals, including the irrepressible Amelia Earhart, along with familiar friends Teddy Roosevelt and Octavius, Larry will stop at nothing to restore the Smithsonian before dawn.' FROM games WHERE igdb_id = 5073 ON CONFLICT (game_id, language_code) DO NOTHING;
