INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tinier Me', 'An anime inspired virtual world where you can customize your own personal avatar, dress up, chat, blog, explore and interact with others, and play online games for free! One of TinierMe‘s most attractive features are the abundant number of lavish outfits to choose from shirts, skirts, hairstyles, accessories… Customize your appearance and create your own original SELFY.' FROM games WHERE igdb_id = 327215 ON CONFLICT (game_id, language_code) DO NOTHING;
