INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Demon''s Souls', 'A third-person action RPG with cooperative and competitive multiplayer elements in which the player enters the kingdom of Boletaria as it is being ravaged by a fog that spawns murderous demons. The player has to hunt down the arch demons situated in five disparate areas within the kingdom and partake in punishing combat to reach the Old One, the vengeful being that brought the fog to Boletaria.' FROM games WHERE igdb_id = 5619 ON CONFLICT (game_id, language_code) DO NOTHING;
