INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Batman: Arkham Asylum', 'Batman: Arkham Asylum is an action-adventure game developed by Rocksteady Studios and published by Warner Bros. Interactive Entertainment. Released in 2009, it follows Batman as he battles the Joker, who seizes control of Arkham Asylum and frees its inmates. The game features stealth, combat, and detective elements, with players using Batman''s gadgets and skills to subdue enemies and solve puzzles. Set in a dark, immersive version of Gotham, the story explores Batman’s psychological battle with his foes, including Harley Quinn, Bane, and Scarecrow. The game received critical acclaim for its gameplay, atmosphere, and storytelling, becoming a defining title in superhero video games.' FROM games WHERE igdb_id = 500 ON CONFLICT (game_id, language_code) DO NOTHING;
