INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Totally Spies!: My Secret Diary', 'Totally Spies!: My Secret Diary is a Nintendo DS game that provides a secure and engaging platform for players to store their secrets. The game includes a password-protected diary, various mini-games, personality tests, fortune cookies, and a crystal ball. Players can also send secret messages and invitations to friends, enhancing the interactive experience.' FROM games WHERE igdb_id = 348995 ON CONFLICT (game_id, language_code) DO NOTHING;
