INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Natalie Brooks: Secrets of Treasure House', 'Search a house of secrets for a lost inheritance in Natalie Brooks - Secrets of Treasure House Deluxe. Solve perplexing puzzles and uncover masterfully hidden items on your quest to help Natalie track down her inheritance. Featuring hundreds of hidden objects and dozens of puzzles, Natalie Brooks - Secret of Treasure House Deluxe is a riveting hidden object adventure.' FROM games WHERE igdb_id = 54247 ON CONFLICT (game_id, language_code) DO NOTHING;
