INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DinerTown Tycoon', 'The evil Grub Burger fast food chain has bribed their way into DinerTown and is threatening to drive out the local diners with their cheap prices, sneaky tactics and the mysterious Ingredient X! It is up to you to take charge and help Flo and the people of DinerTown before it’s too late. Use your restaurant savvy and business smarts to stock the right ingredients, set fair menu prices and purchase new décor and advertising to make the diners successful again. Bring wholesome food and local eateries back to DinerTown to give Grub Burger the boot once and for all.' FROM games WHERE igdb_id = 15000 ON CONFLICT (game_id, language_code) DO NOTHING;
