INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shin Gyakuten Touhou', 'Shin Gyakuten Touhou is a visual novel & adventure style game based on the Gyakuten Saiban/Ace Attorney series. The player assumes the role of Aya Shameimaru as a defense attorney as she proves her clients not guilty using investigation, evidence, and cross-examination. Shin Gyakuten Touhou is the completion of the original game (Comiket 74, 2008) with three primary cases and an extra trial where Aya faces overwhelming evidence as an unpopular celestial Tenshi is accused of stealing.' FROM games WHERE igdb_id = 176003 ON CONFLICT (game_id, language_code) DO NOTHING;
