INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chindouchou!! Pole no Daibouken', 'This is a parody of platforming games and videogames in general. It''s full of secrets, jokes and try&terror-traps that aren''t meant to be serious. Old-school gameplay and audiovisuals make this a charming title and for only 500 Wii Points many are really curious about this one!' FROM games WHERE igdb_id = 50992 ON CONFLICT (game_id, language_code) DO NOTHING;
