INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lego-rock-band', 2695, '2009-11-03', 77, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1wpb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/qzdwwc2mv2kkumjleau2.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LEGO Rock Band', 'LEGO Rock Band is a blending of Rock Band and LEGO series. Players get to start a band and hire band members who will play with them. Just like with real Lego, players can mix and match bodies, torsos, legs and heads to create a character any way they want. The main game has players touring around the world at various locations, like the original Rock Band games. Unlike Rock Band however, LEGO Rock Band also has special levels where you must perform outrageous tasks such as fighting an octopus or demolishing a building using your rock concert. As players make their way through the song lists, they earn "Studs", the game''s currency. Studs can be used to purchase Lego items to decorate your Rock Den, hire new staff, buy new clothes or instruments.' FROM games WHERE igdb_id = 2695 ON CONFLICT (game_id, language_code) DO NOTHING;
