INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Avenue Flo', 'It’s up to you to save the biggest wedding in DinerTown’s history! Playing as Flo, the spunky heroine from Diner Dash, you’ll meet quirky neighbors, solve puzzles, and collect missing items in this fun puzzle adventure game. Enjoy colorful artwork and a lovable cast of characters in the charming world of DinerTown. Search for lost pets, sew beads onto the wedding dress, and more as you help Flo save the wedding!' FROM games WHERE igdb_id = 18878 ON CONFLICT (game_id, language_code) DO NOTHING;
