INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marble Saga: Kororinpa', 'An action puzzle game made for Wii - Wii Balance Board support, Miis, Nintendo Wi-Fi Connection, and Level Editor all in one! Set out on an adventure with Anthony the Ant on his quest through the Ant World. Gather essential items along the way in the ultimate goal to reach the Golden Sunflower and save Anthony''s colony. Face treacherous mazes, use awesome gadgets and balance the world (literally) with fun and intuitive controls only available on Wii. Supports Wii Balance Board As of May 20, 2014, the Nintendo Wi-Fi Connection service for Nintendo DSi and Wii systems has been retired. Online features of this game are no longer available after this date but this game still provides an entertaining experience in offline mode.' FROM games WHERE igdb_id = 4962 ON CONFLICT (game_id, language_code) DO NOTHING;
