INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hakuoki Zuisouroku', 'Zuisouroku fills in the gaps in the Hakuouki story. You can see the everyday lives of Chizuru and the Shinsengumi members. Discover secrets that the men didn''t tell you in the original game and unlock scenarios that are only mentioned briefly in the main story. Retrace the routes and see new scenes for yourself. This game contains more heart melting moments, delicately drawn CGs and fully voiced scenes. Come meet the Shinsengumi swordsmen and tame the bloodthirsty monster within them.' FROM games WHERE igdb_id = 62881 ON CONFLICT (game_id, language_code) DO NOTHING;
