INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Saboteur', 'Experience the ultimate open-world action/adventure as The Saboteur. Fight, climb, and race your way through a uniquely stylized version of Nazi-occupied France, and hunt down your sworn enemies who have taken everything from you. Enter the seedy underground world of a saboteur living in 1940s Paris, where the women are sexy, the missions are epic, and the revenge is satisfying.' FROM games WHERE igdb_id = 3171 ON CONFLICT (game_id, language_code) DO NOTHING;
