INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lethal RPG Destiny: Rebirth', 'Lethal is reborn in this remake of one of my most popular rpgs. You play as Lethal, a half demon half human who once ruled a kingdom. However the human race rallied together and destroyed him. Now he''s back and he''s got revenge on his mind. Conquer the map and reclaim your kingdom in this turn based rpg.' FROM games WHERE igdb_id = 309094 ON CONFLICT (game_id, language_code) DO NOTHING;
