INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('teenage-mutant-ninja-turtles-turtles-in-time-re-shelled', 21848, '2009-08-05', 54, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2y22.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar83q.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Teenage Mutant Ninja Turtles: Turtles in Time Re-Shelled', 'Teenage Mutant Ninja Turtles: Turtles in Time Re-Shelled is an enhanced remake of the 1991 arcade game, Teenage Mutant Ninja Turtles: Turtles in Time, which itself is a sequel to the original Teenage Mutant Ninja Turtles arcade game. Both of the original arcade games were produced by Konami. It is a side scrolling beat ''em up, mostly based on the 1987 animated series, the Teenage Mutant Ninja Turtles Adventures and the second movie. It was developed and published by Ubisoft Singapore for the PlayStation 3 and Xbox 360. It was released worldwide on August 5, 2009 on Xbox Live Arcade and September 10, 2009 on the PlayStation Network. The game was later delisted from the Xbox Live Marketplace and the PlayStation Store in June 2011, due to an expired license.' FROM games WHERE igdb_id = 21848 ON CONFLICT (game_id, language_code) DO NOTHING;
