INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mega Man Rocks!', 'Mega Man Rocks! is a Mega Man fan game created by Eric Ruth via Game Maker and released in April 2009. This game is slightly different from regular Mega Man games, for example, Mega Man can crouch to avoid enemy attacks. Some of the Robot Masters are immune to an uncharged buster shot, making things slightly more complicated.' FROM games WHERE igdb_id = 322021 ON CONFLICT (game_id, language_code) DO NOTHING;
