INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Ball Z: Dragon Battlers', 'Data Carddass Dragon Ball Kai Dragon Battlers was released in 2009 only in Japan, in arcade. It was the first game to have Super Saiyan 3 Broly as well as Super Saiyan 3 Vegeta. This game is based off of characters from Dragon Ball Z. The game''s main feature is having two characters use a team attack such as Gotenks and Gogeta or Cell and Frieza. The graphics are similar to Dragon Ball Z: Budokai 3 and Dragon Ball Z: Infinite World.' FROM games WHERE igdb_id = 78235 ON CONFLICT (game_id, language_code) DO NOTHING;
