INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Toshinden', 'Toshinden is a Fighting game published by Takara Tomy released on December 10, 2009 for the Nintendo Wii. Toshinden is a wii fighting game with beautiful graphics and excellent fighting styles. Choose from several characters and face off on a 3-D fighting style as you move freely around the stage. The game contains story mode, arcade, and combo manager. In the story mode, experience a great story with anime cut scenes. Have fun fun in a more complex fighting style. This game will dazzle you with graphics and sound.' FROM games WHERE igdb_id = 67761 ON CONFLICT (game_id, language_code) DO NOTHING;
