INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Quest IX: Sentinels of the Starry Skies', 'In Dragon Quest IX: Sentinels of the Starry Skies, players begin their adventure as a city guardian who is sent to retrieve a sacred trees fruits, which have the power to grant wishes. Players travel the world, conquer fearsome monsters and unravel an epic storyline. During their journey, players will encounter mighty opponents in fast-paced battles, and also interact with a colorful cast of characters.' FROM games WHERE igdb_id = 1820 ON CONFLICT (game_id, language_code) DO NOTHING;
