INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Darkfall', 'Darkfall (also known as Darkfall Online) is a massively multiplayer online role-playing game (MMORPG) released 2009 by Aventurine SA that combines real-time action and strategy in a fantasy setting. Featuring unrestricted PvP, complete looting, and a player skill dependent combat system, Darkfall is the only MMO to offer such freedom and has spawned a huge community. Aventurine has sold the license of Darkfall Online to two independent companies, Ub3rgames and Big Picture Games.' FROM games WHERE igdb_id = 23000 ON CONFLICT (game_id, language_code) DO NOTHING;
