INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mario-luigi-bowser-s-inside-story', 3363, '2009-02-11', 96, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co21vr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/oiqinybnuh6wanbhpeqb.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario & Luigi: Bowser''s Inside Story', 'Mario & Luigi: Bowser''s Inside Story is the third game in the Mario & Luigi series of games. Players control Mario and Luigi simultaneously in the side-scrolling platform environment of Bowser''s body, while also controlling the Koopa King himself in the top-down world of the Mushroom Kingdom. Similar to games like Earthbound, enemy encounters are seen as actual enemies that players can avoid or attempt to strike early. The actual battles are a combination of turn-based menu attacks, and timed reactions to enemies during battle. By watching the way an enemy reacts, you can anticipate their attack and avoid it or counterattack.' FROM games WHERE igdb_id = 3363 ON CONFLICT (game_id, language_code) DO NOTHING;
