INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ice Breaker', 'Ice Breaker is a physics-puzzle game released January 4, 2009, and is the first installment of the Ice Breaker series. The player must use the mouse to cut ice and objects to get the vikings to their longboat. This game, along with twelve other games, was made a distributable game on August 25th, 2011, and was one of the first distributable games.' FROM games WHERE igdb_id = 280330 ON CONFLICT (game_id, language_code) DO NOTHING;
