INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lady Popular: Fashion Arena', 'Each player begins the game by creating their female character, called "Lady". After the creation of the Ladies, a player can change her appearance (hairstyle, makeup, etc.), create clothes for Lady, rent an apartment and decorate it, cooperate with other players in clubs and party missions, communicate with other Players, play duels at Fashion Arena, communicate using them in the game, post comments and chat, increase their popularity and compete with them in the competition for the best lady, the best apartment and the best party.' FROM games WHERE igdb_id = 351050 ON CONFLICT (game_id, language_code) DO NOTHING;
