INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Picross 3D', 'Picross 3D is the sequel to the popular Picross DS puzzle game. The original game was a number-based grid puzzle that challenged players to reveal a hidden picture. Picross 3D moves the action into three dimensions. Picross 3D blends the logical challenge of a sudoku puzzle with the excitement of discovering the hidden images within.' FROM games WHERE igdb_id = 10631 ON CONFLICT (game_id, language_code) DO NOTHING;
