INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sunday & Magazine: White Comic', 'Shōnen Sunday & Shōnen Magazine White Comic (少年サンデー＆少年マガジン WHITE COMIC) is a RPG video game released by Konami for Nintendo DS on October 15, 2009 in Japan. The game is a crossover featuring several characters from manga published in Weekly Shōnen Sunday and Weekly Shōnen Magazine, including Ghost Sweeper Mikami, Zettai Karen Children, Urusei Yatsura, Ranma ½, InuYasha, History''s Strongest Disciple Ken''ichi, Hayate the Combat Butler, Touch, Detective Conan, Kindaichi Case Files, GodHand Teru, Cyborg 009, Love Hina, Rave Master, Fairy Tail, Code:Breaker and other manga series.' FROM games WHERE igdb_id = 61448 ON CONFLICT (game_id, language_code) DO NOTHING;
