INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Guitar Hero: Van Halen', 'Guitar Hero: Van Halen lets you stand in the shoes of this Rock and Roll Hall of Fame band as you perform 25 epic Van Halen tracks, three signature Eddie Van Halen solos and 19 guest act tracks. Get the crowd roaring with your arena rock stylings on Van Halen hits like Jump, Hot for Teacher, Ain''t Talkin'' ''Bout Love and Dance the Night Away, as well as songs like Billy Idol''s White Wedding, Foo Fighters'' Best of You and Blink-182''s First Date. Experience the excitement of playing as this ultimate party band as you rock out to dozens of enduring hits and prove you have the talent and the style to live up to the Van Halen legend.' FROM games WHERE igdb_id = 2675 ON CONFLICT (game_id, language_code) DO NOTHING;
