INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Infamous', 'Infamous is a single player open-world action/adventure game that places you in the role of Cole McGrath, a once regular guy who in the aftermath of a horrific catastrophe finds himself not only alive, but developing a fantastic array of superpowers. Going from ordinary to extraordinary overnight isn''t something to take lightly. With these powers does one exact revenge? Protect the innocent? Or perhaps, dabble in a little of both? The choice is yours in Infamous.' FROM games WHERE igdb_id = 523 ON CONFLICT (game_id, language_code) DO NOTHING;
