INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nickelodeon Game Builder: Fanboy & Chum Chum', 'Game Builder was a flash game on Nick.com that was released in 2009. It allowed users to create their own levels using assets based on Nickelodeon properties. Unfortunately, it''s now considered lost media after the server was shut down in 2013.' FROM games WHERE igdb_id = 326001 ON CONFLICT (game_id, language_code) DO NOTHING;
