INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gratuitous Space Battles', 'Who needs backstory? Who needs resource-gathering? Diplomacy is so last year. Gratuitous Space Battles cuts right to the chase of sci-fi strategy games, and deals with large, completely unjustified space battles between huge opposing space fleets.' FROM games WHERE igdb_id = 6256 ON CONFLICT (game_id, language_code) DO NOTHING;
