INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('wolfenstein', 569, '2009-08-18', 81, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1y02.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ngluplnvr4cjf5c5dln0.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wolfenstein', 'Wolfenstein is the direct sequel to Return to Castle Wolfenstein and Spear of Destiny/Wolfenstein RPG. It featured a "re-imagined" disguised dark-haired B.J. Blazkowicz, retaining the unshaven look seen in Return to Castle Wolfenstein and dressed in civilian clothes rather than his usual military uniform. The game mainly consists of the player shooting his way through hordes of different types of Nazis, ranging from normal soldier to ninjas. To deal with the large amount of enemies, the player has access to many typical WWII-weapons like the German MP40 or K98 rifle. In addition, during the course of the game he finds the medallion and learns four powers. While at first entering the Veil only allows him so see enemies more clearly and use strange flying creatures as bombs, he is later able to slow down time, surround himself with a protective shield or make himself stronger. However, the medallion''s powers drain its energy, which needs to be refilled at power-spots that are nearly invisible in the real world.' FROM games WHERE igdb_id = 569 ON CONFLICT (game_id, language_code) DO NOTHING;
