INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('evasive-space', 51018, '2009-02-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3ocz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/zvmolfdj1iphvhshz1st.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Evasive Space', 'Twinkle, twinkle, little star, how I wonder WHERE you are... The universe is going dark and it''s up to you Konki, Stellar Guardian, to put things right. Dr. Dark Matter and his roving band of space thieves have stolen many of the Constellation Stones that make up the heavens. Some stones have been sold to unscrupulous space types while others were lost during the getaway. Whatever the situation, you must come through. Suit-up, power-up, and live up to the task at hand. Recover the lost Constellation Stones and once again bring light to the night sky. Guide Konki on timed and collection based missions through 20 stages of varying mazes and obstacles, spanning treacherous terrains including asteroid belts, planetary rings, astro-caves, and large space stations. Hazards surround your every move - enemy fire, asteroids, black holes, tight corridors - while ship upgrades tempt you at every turn.' FROM games WHERE igdb_id = 51018 ON CONFLICT (game_id, language_code) DO NOTHING;
