INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Project X: Love Potion Disaster', 'Project X: Love Potion Disaster is fan-erotic game based on Sonic The Hedgehog universe. The gameplay is 2D scrolling beat''em up, where you play for the character, that you choose at the beginning. You have a choice of 7 characters: R-02 Zeta, Amy Rose, Rouge The Bat, Blaze The Cat, Cream The Rabbit, Miles "Tails" Prower and Zu The Cat. Your goal is to reach the end of the level. Along the way, you will meet enemies that you need to kill to reach the end of the level.' FROM games WHERE igdb_id = 218729 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 218729 AND ge.slug = 'hack-and-slash-beat-em-up' ON CONFLICT DO NOTHING;
