INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('eco-shooter-plant-530', 20506, '2009-11-24', 40, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3djb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/bdmkpegym9movfudok5q.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eco Shooter: Plant 530', 'Battle renegade cans controlled by invading aliens with your trusty recycle cannon and a can-do attitude! The earth’s empty cans have been brought to life by the Cannoids, an alien race determined to destroy the planet. Only Mack, a technician from the recycling facility Plant 530, stands in their way as Earth’s last line of defense. Step into Mack’s shoes in this guided first-person shooter as he takes on the invading aliens with only his trusty recycle cannon and a can-do attitude. Blast and vacuum (yes, vacuum) your way to victory, by keeping in mind that every shot counts—because your ammo also doubles as your health, and every enemy you destroy leaves behind Can Energy that you can vacuum up and use as ammo. Uncomplicated controls (including optional Wii Zapper support) give everyone the chance to save the earth, while advanced tactics like consecutive hit combos and the tough Challenge mode give even the best players a run for their money. Are you ready to step up and put a dent in their cans?' FROM games WHERE igdb_id = 20506 ON CONFLICT (game_id, language_code) DO NOTHING;
