INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('forza-motorsport-3-limited-collectors-edition', 47471, '2009-10-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/ibs2lpdnwvdsjk9xh9sa.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Forza Motorsport 3: Limited Collector''s Edition', 'Forza Motorsport 3 unites the racing game genre, making it possible for everyone to experience the thrill of the world''s most exotic and exquisite cars. Live the most realistic racing experience ever as you take the wheel of more than 400 of the most-beloved cars on over 100 renowned real-world tracks and exotic road courses from around the globe. With breathtaking high-definition graphics and the most advanced vehicle performance modeling in a video game, Forza Motorsport 3 includes a host of driving assists and adjustable skill levels to make the game a gripping pick-up-and-play experience for audiences of all ages and skill levels. The Limited Collector''s Edition gives aspiring drivers, tuners and painters instant VIP Membership status within the Forza community including special recognition in the new Storefront feature as well as the online Auction House, scoreboards, ForzaMotorsport.net and more. As a VIP member, consumers gain exclusive access to some of the world''s hottest cars. In addition, the LCE features exclusive designs and tuning kits and comes with a Forza Motorsport 3 collector''s keychain, an exclusive Collector''s Car Pack and a 2GB USB thumbdrive in which you can store your favorite Forza videos, photos and designs to easily share them with friends.' FROM games WHERE igdb_id = 47471 ON CONFLICT (game_id, language_code) DO NOTHING;
