INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trials HD', 'Trials HD is a full-featured, physics-based motorcycle racing game with more than 50 tracks in two unique game modes. Race Mode emphasizes balance, skill, and control as you tackle indoor obstacle tracks. Skill Mode features extreme skill games in which explosions, crashes, and injuries cannot – and sometimes should not – be avoided.' FROM games WHERE igdb_id = 2145 ON CONFLICT (game_id, language_code) DO NOTHING;
