INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eufloria', 'Eufloria is an ambient game of space exploration and conquest that employs surprising themes of plant growth and bio mechanical evolution. The game allows the player to explore a beautifully realized universe rendered in a style that is both unique and compelling.' FROM games WHERE igdb_id = 7596 ON CONFLICT (game_id, language_code) DO NOTHING;
