INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Megaplex Madness 2: Summer Blockbuster', 'After much success refurbishing Movieville''s cinemas, you''ve decided to build the town a movie megaplex with 5 uniquely-themed theaters. Use your fast fingers to serve movie goers and make cash to buy upgrades. Hit Expert level to earn tokens for arcade mini-games and hit Master level to choose theater decorations, like a rocket for your sci-fi theater.' FROM games WHERE igdb_id = 352383 ON CONFLICT (game_id, language_code) DO NOTHING;
