INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars: Battlefront - Elite Squadron', 'Fight epic all-in-one battles spanning ground, space and capital ship connected battlefronts. Use classic Star Wars vehicles to travel from the ground, up into the air and then into space where you will continue the battle among, and even aboard, enormous Capital Ships. Immerse yourself in an engrossing original story campaign that spans the entire Star Wars saga and beyond, plus engage expanded gameplay features like deeper character customization, hundreds of unlockable achievements, new multiplayer stats, deadly new weapons, new heroes and villains, new Star Wars worlds and much more!' FROM games WHERE igdb_id = 476 ON CONFLICT (game_id, language_code) DO NOTHING;
