INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Amazing Adventures Around the World', 'Pieces of an ancient stone tablet have started turning up around the globe and the Museum needs your help to locate the pieces and find the most expensive gem ever known...the World Diamond. Under the direction of the Museum, you must immediately begin your global seek & find adventure. Complete over 100 levels by finding hidden objects and circumventing unique puzzle traps.' FROM games WHERE igdb_id = 15711 ON CONFLICT (game_id, language_code) DO NOTHING;
