INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Warfare 1944', 'Warfare 1944 is the second game in the Warfare series, it is a sequel to Warfare 1917.  The game is set during Operation Overlord, the invasion of Normandy, during the Second World War. The player can choose to play as either the invading US Forces or the defending Wehrmacht.' FROM games WHERE igdb_id = 61589 ON CONFLICT (game_id, language_code) DO NOTHING;
