INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('burya-v-stakane-honky-na-marshrutkakh', 336186, '2009-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9kag.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scvstf.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Burya v Stakane: Honky na Marshrutkakh', 'The operational situation in the vast expanses of the Far Northern Galaxy has become much more complicated. Persons of unknown nationality are operating everywhere. The production of illegal alcohol has been established on secret planets on a galactic scale. In the game Storm in a Teacup: Minibus Racing, two seasoned employees of the Krishna Operatives sect are sent to carry out a complex of operational-search activities. To restore order in the region, the operatives will have to solve many problems: free Princess Zadolballa, assemble a proton torpedo, and stop the illegal production of robotics. And in the meantime, find the Chosen One, whose appearance was predicted by the Oracle, rescue the great and secret Ch., steal a starship - in a word, demonstrate operational ingenuity. And our heroes will be helped by talented racers: rapper Nikolai Beldyev, the beautiful Zhuzhu, the young and very promising Enikey Skovorodker and others.' FROM games WHERE igdb_id = 336186 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 336186 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
