INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('backyard-football-10', 4688, '2009-10-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co55u8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scehds.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Backyard Football ''10', 'Backyard Football ''10, features new co-op play for exciting 2 vs 2 action and is packed with a roster full of NFL superstars featured as animated middle-schoolers in the game. The game featuring top NFL players as kids and combines realistic NFL plays and strategies with wild arcade style power moves and comical scenarios so gamers of all ages can learn the fundamentals of football while having fun. Multiple levels make it easy enough for beginners, yet challenging enough for even die-hard football fans. In addition to new co-op, 2 vs. 2 multi-player action, Backyard Football ''10 features enhanced controls, new unlockables, insane power ups, custom teams and characters, multiple play modes (single player, season play, tournament and all-pro) as well as a hall of fame from Backyard Football ''09.' FROM games WHERE igdb_id = 4688 ON CONFLICT (game_id, language_code) DO NOTHING;
