INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Musou Orochi Z', 'Musou Orochi Z, is a 2009 hack and slash video game developed by Koei and Omega Force for the Sony PlayStation 3 and Microsoft Windows. Z is the third installment of the Warriors Orochi series, a crossover video game of the Dynasty Warriors and Samurai Warriors series. Musou Orochi Z was intended to be a combination of the first two games with more characters and stages on an updated gaming platform. The game was released in Japan for PlayStation 3 on March 12, 2009 and released on Microsoft Windows platform on November 27, 2009. Koei had planned to release the game as Warriors Orochi Z in North America and Europe, but those plans have since been cancelled.' FROM games WHERE igdb_id = 7480 ON CONFLICT (game_id, language_code) DO NOTHING;
