INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Radirgy Noa', 'Radirgy Noa (also written as Radirgynoa) is a vertically scrolling shoot ''em up that was released in June 2009 for the Sega Naomi arcade platform by Milestone Inc. and the sequel to Radirgy. It was later released on February 25, 2010, in Japan for the Wii under the name Radirgy Noa Wii, distributed by LUCKY Co. LTD. It was also ported to the Xbox 360 on October 28, 2010, with new features, as Radirgy Noa Massive. A Microsoft Windows version was released on February 25, 2011, as part of the Milestone Sound Collection.' FROM games WHERE igdb_id = 254475 ON CONFLICT (game_id, language_code) DO NOTHING;
