INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('another-code-r-a-journey-into-lost-memories', 4676, '2009-02-05', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4ole.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4qui.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Another Code: R - A Journey into Lost Memories', 'Another Code: R is the sequel to the critically acclaimed Nintendo DS game Another Code. The Wii sequel is set 2 years on from Another Code but in the same universe and will also follow the familiar heroine, Ashley. After solving the mystery of her father''s disappearance in the first Another Code, Ashley is now on the traces of her late mother and trying to unravel the mystery of her death. On her adventure at Lake Juliet''s Camp, Ashley will investigate several locations, and encounter several characters; some of which know more than they tell her on her mother''s past. Ashley will also face several puzzles which can be solved by carrying out various actions with the Wii Remote, and find items amongst the camp.' FROM games WHERE igdb_id = 4676 ON CONFLICT (game_id, language_code) DO NOTHING;
