INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Madden NFL 10', 'Madden NFL 10 also lets you take your fight online with an all-new Online Franchise mode, complete with 32 teams, NFL-style drafts and a custom league webpage. Add to that the most immersive broadcast presentation to date, and Madden NFL 10 gives you everything you see on Sundays, minus the grass.' FROM games WHERE igdb_id = 4985 ON CONFLICT (game_id, language_code) DO NOTHING;
