INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sanae no Youkai Taiji Shinan', 'Sanae''s Youkai Extermination Lesson is a top-down shooter by doujin circle GATLING CAT (the developers of Touhou Katsugeki Kidan), starring Sanae Kochiya and Momiji Inubashiri. Its gameplay is similar to that of Taito''s Kiki Kaikai/Pocky & Rocky shooter series.' FROM games WHERE igdb_id = 360893 ON CONFLICT (game_id, language_code) DO NOTHING;
