INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '1000 Words', '1000 Words tells the story of a little girl whose family is falling apart. One day she meets an artist, and asks him to teach her how to draw better. He answers that she just has to train everyday, and a few years later she''ll get better. But that''s too slow to her; there''s no time.' FROM games WHERE igdb_id = 322687 ON CONFLICT (game_id, language_code) DO NOTHING;
