INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-almost-heaven-crisis', 124040, '2009-10-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1rxe.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc77h6.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Almost Heaven Crisis', 'The Almost Heaven Crisis is an isometric survival game. The world plays on whether you take action or not. Day becomes night, blue skies turn to thunder and lightning. And zombies will take over the world unless you stand up and fight against them! The other villagers aren''t useless- they will try their best, and those armed with guns will attempt to take down the zombies. However, the zombies are fast-moving and strong and with out your help it could be a lost cause.' FROM games WHERE igdb_id = 124040 ON CONFLICT (game_id, language_code) DO NOTHING;
