INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tokimeki Memorial 4', 'Tokimeki Memorial 4 is a dating sim developed and published by Konami, the fourth game in the Tokimeki Memorial series and also the first original game in the series to debut on a portable system. The game celebrated the 15th anniversary of the Tokimeki Memorial franchise. A special edition package of the game included an OVA, the soundtrack, a character box, and sketches from the artists of the game. It also featured the return of the Tree of Legend from the first Tokimeki Memorial game, as well as the return of the Kirameki High school setting, set 15 years after the first game.' FROM games WHERE igdb_id = 67379 ON CONFLICT (game_id, language_code) DO NOTHING;
