INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Action Bowling Classic', 'Action Bowling Classic is a pioneering 3D bowling simulation game that debuted on mobile phones on January 13, 2009. Developed by Tribal City Interactive in collaboration with Kronos Games Online, it quickly became a staple in the mobile gaming scene, celebrated for bringing a remarkably realistic bowling experience to the palm of your hand.' FROM games WHERE igdb_id = 343475 ON CONFLICT (game_id, language_code) DO NOTHING;
