INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bounce Evolution', 'Bounce Evolution is a fully playable technology demonstration of the impressive gaming and 3D capabilities of the Nokia N900. Use the intuitive motion control to guide Bounce through beautiful countryside scenery, race against time on the futuristic racing track, or just enjoy beautiful landscape in the non-interactive demo. The game is rendered using OpenGL ES 2.0 hardware acceleration allowing the game''s next-generation graphics to run smoothly on the sharp 800 x 480 display.' FROM games WHERE igdb_id = 331773 ON CONFLICT (game_id, language_code) DO NOTHING;
