INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Swords & Soldiers', 'Rewrite history as you take control of the brutal Vikings, the devious Aztecs or the crafty Chinese in their global quest to win the favour of the Gods! Swords & Soldiers is a side-scrolling strategy game that lets you control an entire army and lets you wield devastating magical abilities. Demolish your enemy’s castle at the end of these two-dimensional battlefields and lead your troops to victory!' FROM games WHERE igdb_id = 10783 ON CONFLICT (game_id, language_code) DO NOTHING;
