INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gyakuten Touhou 2', 'The game is the second entry in the Gyakuten Touhou series. The game follows Aya Shameimaru as a defense attorney who investigates four cases. The gameplay is mostly the same as in the previous game, divided into two types of phases: investigations, where Aya searches the crime scene for evidence and talks to witnesses, and rebuttals to learn new information. During the courtroom sections, Aya defends their client and cross-examines the witnesses''s testimonies using the evidence found during the investigations.' FROM games WHERE igdb_id = 178365 ON CONFLICT (game_id, language_code) DO NOTHING;
