INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('our-house-party', 50666, '2009-10-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co74vm.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Our House: Party!', 'You''re invited to a do-it-yourself party with power tools! Your tool belt needs only the Wii Remote and Nunchuk in it to hammer, saw, paint and more in Our House: Party!, the fast-paced, house-renovating party game in which players compete in numerous home-improvement projects! Players race through the home store picking up valuable tool upgrades and then compete in a series of mini-games to earn upgrades and increase the value of their custom homes! Features • Your Dream House: Complete home-improvement projects in fast-paced, party action to earn upgrades and increase the value of your custom home! • The Ultimate Tool: Use the Wii Remote as your ultimate house-building tool to nail, cut, mow and much more! • Do-It-Yourself Projects: More than two dozen projects such as Bathroom Remodel and Garden Renovation are composed of over 175 mini-games including Hammer Time, Demolition Derby, Green Thumb and many more! • House Styles: Choose from Gingerbread, Lancelot, Modern and other styles. • All Mixed Up: True modular home construction enables endless combinations that create personalized trophy homes. • Register Race: It’s a mad rush through The Home Depot to pick up power-ups such as nail guns and riding mowers! • Multiplayer: Play against up to 3 friends for hours of “tooling” around! • WiiConnect24: View the progress of friends’ houses on a virtual street within The Neighborhood Mode' FROM games WHERE igdb_id = 50666 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 50666 AND p.igdb_id = 5 ON CONFLICT DO NOTHING;
