INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zombie Shooter 2', 'Zombie Shooter 2 is a unique blend of two game genres - Action and RPG. Every player can choose a character to the liking, get experience to develop skills, earn money and spend it at weapons, medications and useful devices. All of this will be used against thousands of enemies. The zombies fill the game screen, never letting you rest, even for a minute.' FROM games WHERE igdb_id = 16018 ON CONFLICT (game_id, language_code) DO NOTHING;
