INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harry Potter and the Half-Blood Prince', 'Harry Potter and the Half-Blood Prince features the exploration of Hogwarts and casting spells on objects around the school, similar to its predecessor. The game also includes multiplayer games, classes, different times of day, Quidditch, Wizard Duels and Potion making. The Marauder''s Map is included in the game, with progress opening other parts of the school. Harry can also call Nearly Headless Nick to show him around the school. Harry is the main playable character in the game, but Ron and Ginny are also available in two levels.' FROM games WHERE igdb_id = 4906 ON CONFLICT (game_id, language_code) DO NOTHING;
