INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deathsmiles II: Makai no Merry Christmas', 'Deathsmiles II: Makai no Merry Christmas is a horizontal side scrolling shoot ''em up arcade game by Japanese developer Cave, released in 2009. It is the third Cave shoot ''em up to be played using a horizontally-oriented monitor (preceded by Progear and the original Deathsmiles). Deathsmiles II is also the first CAVE arcade game to use polygons instead of their traditional sprites for graphics.' FROM games WHERE igdb_id = 68011 ON CONFLICT (game_id, language_code) DO NOTHING;
