INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '0D Beat Drop', '0-D Beat Drop is a 2009 rhythm-puzzle video game developed by Cyclone Zero and published by Aksys Games and Arc System Works. With elements of Puyo Puyo and Lumines, the game has players organizing colored shapes onto a playing field in order to match three pieces and clear them using the game''s titular Beat Drop, which requires the player to listen to the techno soundtrack.' FROM games WHERE igdb_id = 6173 ON CONFLICT (game_id, language_code) DO NOTHING;
