INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Touhou Unreal Mahjong', 'Touhou Unreal Mahjong is a Mahjong fangame created by D.N.A.Softwares in March 2009 that involves the Touhou Project'' characters, settings, and music released at Reitaisai 6. It, along with the related Magus in Mystic Geometries, are rare examples of ZUN''s contributing to fan-made works.' FROM games WHERE igdb_id = 59894 ON CONFLICT (game_id, language_code) DO NOTHING;
