INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Zelda: Spirit Tracks', 'The Legend of Zelda: Spirit Tracks is the second Zelda game for the Nintendo DS. The art direction is still cel-shading, but the game have notable changes from Phantom Hourglass with more puzzles and a new mode of transportation by train. You have to draw your route to the next area on the map and then let the train run its course. While the train is moving, caution will be needed to avoid obstacles, animals and enemies on the tracks. In certain dungeons, both Link and Zelda will be playable as they will need to work together to solve puzzles.' FROM games WHERE igdb_id = 1038 ON CONFLICT (game_id, language_code) DO NOTHING;
