INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bars of Black and White', 'You can''t remember the last time you left your room. When you receive a barcode reader in the mail, you discover that the world around you is not what it seems, and must escape the bars of black and white. "Bars of Black and White" is a game in the room-escape tradition with hand-drawn line art graphics and novel barcode-scanning action. Is the world insane, or is it you?' FROM games WHERE igdb_id = 263669 ON CONFLICT (game_id, language_code) DO NOTHING;
