INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('drawn-to-life-the-next-chapter', 4820, '2009-10-08', 73, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9bfa.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ctlm18t6ldbzig1rfzav.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Drawn to Life: The Next Chapter', 'Drawn to Life: The Next Chapter is a 2D platform video game developed by 5th Cell and published by THQ for the Nintendo DS, released in October 2009 in all regions except Japan. It is a sequel to the original Drawn to Life and a counterpart to the Wii version, although it has a different plot. One of the game''s major features is the player''s ability to draw elements of the game, and the game has a heavy emphasis on doing so.' FROM games WHERE igdb_id = 4820 ON CONFLICT (game_id, language_code) DO NOTHING;
