INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jane''s Zoo', 'Help Jane cater to her wildest customers yet in Jane''s Zoo, the next exciting adventure for everyone''s favorite hotel heiress. Make sure your furry friends have plenty of food, shelter, and fun in three exciting locations. A wonderful new adventure for everyone''s favorite hotel heiress, Jane''s Zoo also features hidden object bonus rounds, special bonuses to collect, and much more!' FROM games WHERE igdb_id = 25486 ON CONFLICT (game_id, language_code) DO NOTHING;
