INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ys I & II Chronicles', 'Ys: I & II Chronicles is a remake for the PSP of the two first iterations of the critically-acclaimed Ys series. The graphics have been reimagined in HD hand-drawn 2D and the soundtrack newly rearranges, while returning fans have the option of playing with the original music or using alternative character art. Four difficulty levels and a time trial mode have also been added, making this the definitive version of the legendary series’ origin.' FROM games WHERE igdb_id = 21020 ON CONFLICT (game_id, language_code) DO NOTHING;
