INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bleach-heat-the-soul-6', 69255, '2009-03-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1ppq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scnckt.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bleach: Heat the Soul 6', 'Bleach: Heat the Soul 6 is the sixth game in the Heat the Soul series based on Tite Kubo''s Bleach, which was released in Japan on May 14, 2009. It includes more Arrancar Resurrections like that of Nnoitora, Szayelapporo Grantz or Nel(Gamuza). The game has a new championship mode added in which you can fight tournament style similar to Bleach Soul Carnival and a customization mode exclusive to Heat the Soul 6. The game''s story mode starts from the day Ichigo got his powers to the Espada/Soul Reaper showdowns to date in the anime. It boasts an amazing character roster consisting of 74 playable characters including Senna, Sojiro Kusaka, Dark Rukia, and the Visored and Tessai in their Soul Reaper uniforms from the "Turn Back the Pendulum" arc. Its opening theme is "Koyoi, Tsuki ga Miezu Tomo" by Porno Graffitti which was also used for Bleach: Fade to Black.' FROM games WHERE igdb_id = 69255 ON CONFLICT (game_id, language_code) DO NOTHING;
