INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Musubareta Te', 'In the director''s office of the Momoyama Academy, there''s an altar with 3 kokeshi dolls that under no circumstances should be touched. One night, two girls called Shizune and Akari end up trapped inside the school. There, they discover that the dolls have disappeared and when looking for a way out, they find a strange apparition. Could this be related to the wooden dolls?' FROM games WHERE igdb_id = 151769 ON CONFLICT (game_id, language_code) DO NOTHING;
