INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Farm Frenzy 3', 'Manage five farms around the world and try your hand at penguin-breeding and jewelry-making in Farm Frenzy 3! Features 95 outrageously fun levels, 30 wacky animals and more upgrades than there are ears in a corn field! What''s more, as you grow crops, feed animals, collect produce and manufacture goods, you''ll be treated to some of the zaniest animation to ever grace a casual game! Will you help Scarlett become the president of the farmer’s union by earning the votes of the people she helps? Find out when you go back to the farm in Farm Frenzy 3.' FROM games WHERE igdb_id = 16093 ON CONFLICT (game_id, language_code) DO NOTHING;
