INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Virtual Families', 'Adopt and nurture a character and help them live their life inside your computer! Dictate everything form their daily routine to their career in this addicting family simulation game. Earn money to decorate the house, buy groceries, and other essentials.   Shape your character''s personality by rewarding certain behaviours and punishing others. Find suitable mates for all your characters and start your very own perfect Virtual Families!' FROM games WHERE igdb_id = 9394 ON CONFLICT (game_id, language_code) DO NOTHING;
