INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('saira', 15034, '2009-12-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/dsalapxlhifonqoe16iz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/wf4z6lfjf1uqxvj7kigi.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saira', 'Saira is a puzzle platformer with non-linear gameplay and a whole universe for you to explore. The game is heavily influenced by classic puzzle adventure games and uses a new unique graphical style combining high resolution photography into a lush and mysterious world. The eponymous Saira is a photographer who specializes in digitally capturing dangerous places and animals across the universe. For reasons unknown, she finds herself as the only remaining person in the entire galaxy. Saira has no weapons, she will use only her mind and agility to progress through seven star systems and over 60 well-crafted puzzles. Over two hours of originally-scored music will help her maintain focus and unlock one of six vastly unique endings.' FROM games WHERE igdb_id = 15034 ON CONFLICT (game_id, language_code) DO NOTHING;
