INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Touhou Pocket Wars', 'Touhou Pocket Wars is fan-made Touhou Project strategic RPG based around Gacha Figurines. The player plays themselves as a Touhou-character themed Gacha collector, entering tournaments and leveling up their figurines and accompanying spell cards to take on stronger and stronger opponents.' FROM games WHERE igdb_id = 128382 ON CONFLICT (game_id, language_code) DO NOTHING;
