INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('charm-girls-club-pajama-party', 51041, '2009-11-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9pw6.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Charm Girls Club Pajama Party', 'Charm Girls Club Pajama Party is packed with over 30 mini-games that will get girls up dancing, pillow fighting, cooking, racing, spinning, moving, and playing together in ways that will keep them laughing all night! Create your Charm Girls and team up with up to 7 girl friends! Pajama Party has awesome mini-games including Bed Bounce, Speed Hair Teasing, Balloon Bop, Dance Off, Pose Off, Pillow Fight, and more! Earn over 40 virtual charms! Create endless trendy and stylish looks and customize a Charm Girl to reflect your unique style. Choose everything from hair, make-up, wardrobe, shoes and accessories! Completing challenges can earn you sparkly new virtual charms for your jewelry box. Show off your charms to your friends and see who can collect the most!' FROM games WHERE igdb_id = 51041 ON CONFLICT (game_id, language_code) DO NOTHING;
