INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bowman--1', 357273, '2009-03-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa6fx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3wbs.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bowman', 'Bowman is a highly addictive classical game. Even if you''ve never heard of it before, play it just once and you''ll be hooked. The object of the game is to shoot arrows at your opponent and kill them before they kill you. It''s a battle against your opponent to see who can accurately judge the angle and strength of the shot to make the arrow land on your opponents body. A head shot inflicts the most damage while a shot in the chest takes second place. Everywhere else on the opponents body inflicts less damage. To shoot your bow, simply drag your finger across the screen and you''ll be presented with a trajectory plus angle and strength (power) information. Release your finger to release the bow.' FROM games WHERE igdb_id = 357273 ON CONFLICT (game_id, language_code) DO NOTHING;
