INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crunchball 3000', 'Crunchball 3000 is a video game by British developer Ben Olding in which players take part in the titular futuristic sport. They can create and manage teams, play single or multi-player games with preset teams or edit teams.' FROM games WHERE igdb_id = 346564 ON CONFLICT (game_id, language_code) DO NOTHING;
