INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hero''s Arms', 'A good-old Zelda-like adventure game. You''ll need to defeat monsters along the way of the outside world to find dungeons where quest items (or treasures) are kept safe by big monsters. Those relics are then used to grant passage to the evil Gordzak''s lair, which you''ll have to destroy in order to beat the game. To accomplish this you will need to upgrade your gear and your personal strength by leveling up and finding magic items.' FROM games WHERE igdb_id = 346633 ON CONFLICT (game_id, language_code) DO NOTHING;
