INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'R-Type Tactics II: Operation Bitter Chocolate', 'R-Type Tactics II is a turn-based strategy game/tactical role-playing game released in 2009 in Japan for the PlayStation Portable game console. It is the sequel to 2007''s R-Type Tactics, known as R-Type Command in North America. The main part of the game consists of three campaigns, set nine years after the events of Tactics, in which the player controls two human factions, then the Bydo Empire.' FROM games WHERE igdb_id = 44505 ON CONFLICT (game_id, language_code) DO NOTHING;
