INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tropico 3: Steam Special Edition', 'The Steam Special Edition of Tropico 3 contains the following additional content: - Two additional maps for the sandbox mode: Verde Playa, Coco Chico Map - Two additional costumes for the el presidente avatar editor: - Female Avatar: Casual Clothes - Male Avatar: Casual Clothes - Two additional accessories for the el presidente avatar editor: - Female Avatar: Baseball Hat - Male Avatar: Commie Hat Tropico 3 offers a tongue-in-cheek, light-hearted take on real world issues like third world politics, corruption and totalitarian regimes.' FROM games WHERE igdb_id = 29195 ON CONFLICT (game_id, language_code) DO NOTHING;
