INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hands On! Tangrams', 'The Nintendo DS variation of the ancient ‘Chinese Moving Puzzle’ will captivate players of all ages! Solve 100 puzzles in 10 different themed levels and watch them roar to life on your screen! Improve perception skills, logical thinking, and hand-eye coordination in this hands-on adventure that is loaded with fun! Tangrams help to develop positive attitudes towards geometry, promote an understanding of basic geometric shapes and interaction and further shape recognition and organization skills. Using the touch screen to test your perceptual proficiency, Hands On! Tangrams brings manipulative puzzle solving to your Nintendo DS!' FROM games WHERE igdb_id = 48043 ON CONFLICT (game_id, language_code) DO NOTHING;
