INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cursor-star-10-2nd-session', 246712, '2009-02-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6etx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scm7m9.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cursor*10: 2nd session', 'Cursor*10 [2nd session] is the sequel to Cursor*10, a puzzle game where the player controls a cursor and the goal is to reach the sixteenth floor of a level in a race against time. During the course of the game, events will loop when time runs out and the player is able to cooperate with a past version of himself, as all the previous actions of the cursor can still be seen and influence the current session. As such, eventually up to ten cursors will cooperate to reach the sixteenth floor, clicking boxes to open them, mounting stairs and pressing buttons simultaneously. The graphics are drawn as outlines in black and white, shown from an isometric perspective. This edition features both recurring and new puzzles, including a deadly spear that can pin your cursor, instantly killing it, and a key to unlock a box. This version also introduces sound, unlike the first game. Apart from that, the gameplay mechanics are completely identical.' FROM games WHERE igdb_id = 246712 ON CONFLICT (game_id, language_code) DO NOTHING;
