INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mini Ninjas', 'Mini Ninjas is a game that combines furious action with stealth and exploration for an experience that appeals to a wide audience across age groups and preferences. It’s an action-adventure with a strong focus on allowing the player freedom to explore the world and has the depth to allow for very varied gameplay and approaches to getting through the game.' FROM games WHERE igdb_id = 2192 ON CONFLICT (game_id, language_code) DO NOTHING;
