INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Age: Origins Collector''s Edition', 'Dragon Age: Origins Collector''s Edition contains : - Tin case. - Bonus DVD including: - A making of documentary - Soundtrack - Trailers - Wallpaper - Concept art video - Strategy tips - Cloth map - 3 pieces of exclusive in-game content: - Bergen’s Honor: A massive helmet made out of dragonbone (+2 to armor, +25 physical resistance, +6 to attack). - Grimoire of the Frozen Wates: A special book that adds +3 to all attributes when read. - Final Reason: A magical staff of immense power (adds to damage, spell power, and fire damage). - "The Stone Prisoner" unlockable bonus quest and unlockable character, Shale. - Exclusive in-game item for use in the upcoming title Mass Effect 2.' FROM games WHERE igdb_id = 21765 ON CONFLICT (game_id, language_code) DO NOTHING;
