INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WarpForce', 'WarpForce is the official expansion to the original AdventureQuest. Join the WarpForce and explore the galaxy while battling the evil alien force known as THE NETWORK. Login with your existing AdventureQuest account and create a new human, drakel, or elf character to begin your adventure. You can play a wide variety of BattleTypes including armored cannonwielder, witty space rogue, quick-fisted ninja, genius cyber tech and more. Level up, train your stats and obtain new weapons, pets, battlesuits, skills & techs!' FROM games WHERE igdb_id = 55876 ON CONFLICT (game_id, language_code) DO NOTHING;
