INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Along Came A Spider', 'Along Came A Spider is a 2D platform game. In a world made of silk, you control a small spider trying to find his way back home through twenty dynamic swinging, swaying levels. Your spider will learn amazing new abilities allowing him to catch many more flies along his way. Your fearless spider must also confront his worst nightmares in four special boss levels!' FROM games WHERE igdb_id = 163364 ON CONFLICT (game_id, language_code) DO NOTHING;
