INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tales of Graces', 'Tales of Graces is an action role-playing game. You will follow Asbel Lhant int he world of Ephinea. In his childhood, Asbet became friends with an amnesiac girl and witnesses her death. However, seven years later, he is reunited with the girl who retains her amnesia...' FROM games WHERE igdb_id = 1211 ON CONFLICT (game_id, language_code) DO NOTHING;
