INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rockman.EXE Operate Shooting Star', 'Rockman.EXE Operate Shooting Star is a game released on November 12, 2009 for the Nintendo DS in Japan. It is an advanced port of the first Mega Man Battle Network game with some extras, including a crossover with the Mega Man Star Force series. Capcom currently has no plans for a release outside of Japan.' FROM games WHERE igdb_id = 1774 ON CONFLICT (game_id, language_code) DO NOTHING;
