INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Uncharted 2: Among Thieves - Fortune Hunter Edition', 'Released via a giveaway on the PlayStation Blog for players in the US only. Only 250 copies were produced and they were distributed through various promotional contests during the first few months after the game''s launch date. The Fortune Hunter Edition includes: - Uncharted 2: Among Thieves - An exact in-game replica of the Phurba Dagger Artifact and stand - Collectible Art Book and Collector case autographed by Naughty Dog - A "host of downloads"' FROM games WHERE igdb_id = 41883 ON CONFLICT (game_id, language_code) DO NOTHING;
