INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crayola Colorful Journey', 'Exploring the Art of Adventure... From the creators of Crayola Treasure Adventures on DS and the most respected brand in households with kids, comes Crayola Colorful Journey Wii, the perfect game for all creative and adventurous boys and girls. Encouraging imagination and creativity, Crayola Colorful Journey Wii gives the player the ability to bring a virtual coloring book to life. Players will be transported into a world where they take on the role of either Fillup or Violet on a quest across Crayola Land.' FROM games WHERE igdb_id = 51047 ON CONFLICT (game_id, language_code) DO NOTHING;
