INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Baby: First Steps', 'Teach your Baby to Walk, Talk, and Play! Your baby has grown so fast! Can you believe that a year has already gone by? Take care of your baby from their 1st birthday until they''re 3 years old. Your baby will discover its entire environment and learn from it, they''ll walk, babble and speak, try to catch every object they can, and put everything in their mouth... Your baby will be the apple of your eye!' FROM games WHERE igdb_id = 47910 ON CONFLICT (game_id, language_code) DO NOTHING;
