INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crash Bandicoot: Mutant Island', 'Crash Bandicoot: Mutant Island is an 2D action platform game for mobile phones based on the better known 3D action platform game. The game starts with Crash''s sister Coco being kidnaped by Cortex. Crash hurries to save his sister and confronts cortex and his giant robot. In the battle that follows, Coco manages to escape but upon return they realise it was all a distraction to kidnap and hypnotize the other Bandicoots.' FROM games WHERE igdb_id = 148198 ON CONFLICT (game_id, language_code) DO NOTHING;
