INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aquarium HD', 'Add a little ambience to your living room with Aquarium HD! It has amazing looking scenes and a variety of different fish, each with its own unique behavior. Aquarium HD is the most realistic looking fish tank game on the XBOX. It’s perfect for entertaining guests and is super-easy for the kids to use. Feed the fish or tap on the glass to make them dart around!' FROM games WHERE igdb_id = 92030 ON CONFLICT (game_id, language_code) DO NOTHING;
