INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fortune Summoners: Secret of the Elemental Stone', '"Fortune Summoners is a side-scrolling, real-time Action RPG made from the mold of some of gaming''s most famous and beloved classic side-scrollers and combined with modern design sensibilities. In it, you will guide Arche Plumfield and her friends through great adventures to uncover the secret of something Arche has discovered - and maybe engage in some Real Heroics on the way!"' FROM games WHERE igdb_id = 12526 ON CONFLICT (game_id, language_code) DO NOTHING;
