INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('zettai-zetsumei-toshi-3-kowareyuku-machi-to-kanojo-no-uta', 11697, '2009-04-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3z3w.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/v1n3ow869oncrsmx9bls.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zettai Zetsumei Toshi 3: Kowareyuku Machi to Kanojo no Uta', 'Zettai Zetsumei Toshi 3: Kowareyuku Machi to Kanojo no Uta is the third game in the Zettai Zetsumei Toshi series. Players can choose to play as a boy (Naoki Kosaka) or a girl (Rina Makimura), both of whom start the game trapped in a bus an underground tunnel after a large earthquake. The two player characters have slightly different attributes, which affect gameplay: Naoki is physically strong and self-confident, but becomes stressed more easily, while Rina is physically weak but has a calmer personality, which causes her stress levels to rise more slowly. The thirst and body temperature meter has been replaced by a stress meter. The meter rises after engaging in angry conversations and witnessing/experiencing various traumatic incidents. The player can choose from several responses during conversations, allowing them to choose how to behave towards fellow survivors. These responses allow the player to control the character''s personality, and also have occasional effects on the character, such as lowering or raising their stress levels. High stress will affect the character''s movements, causing them to have trouble walking. 2-4 players can play cooperatively via ad hoc connection, unlike the first two games, which were only single player.' FROM games WHERE igdb_id = 11697 ON CONFLICT (game_id, language_code) DO NOTHING;
