INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'New Super Mario Bros. Wii', 'New Super Mario Bros. Wii is a side-scrolling 2.5D Mario platformer for the Wii and the tenth game in the Super Mario series. In addition to the single-player experience, New Super Mario Bros. Wii also features a multiplayer mode for up to four players. This is the first Super Mario game to feature co-op and vs. modes at the same time since Mario Bros. It features more items, new levels, and more enemies than the DS predecessor. The game introduces two new power-ups, the Propeller Mushroom and the Penguin Suit, which turn characters into their propeller and penguin forms, respectively.' FROM games WHERE igdb_id = 2178 ON CONFLICT (game_id, language_code) DO NOTHING;
