INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('videocart-27-pac-man', 245385, '2009-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6dpj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scm3wj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Videocart-27: Pac-Man', 'An unauthorized version of Pac-Man. Pac-Man is a game where the eponymous Pac-Man goes around a maze in the cardinal directions munching pellets as he goes. The goal is to eat all the pellets found on the maze. While trying to do this, Pac-Man is harassed by four ghosts (Blinky, Pinky, Inky, and Clyde) who constantly chase him around the maze. If the ghosts touch Pac-Man, he will lose a life. Pac-Man starts with three lives and if he loses all of them the game will end. Pac-Man is not completely defenseless as on each maze, there are four power pellets, that when Pac-Man consumes them, will cause the tides to turn, as Pac-Man will be able to temporarily chase the ghosts to eat them and temporarily send them back to the middle of the maze from whence they came. Pac-Man can also eat randomly appearing fruit to earn bonus points. This version of Pac-Man retains the intermissions found in the original game.' FROM games WHERE igdb_id = 245385 ON CONFLICT (game_id, language_code) DO NOTHING;
