INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PuppetShow: Mystery of Joyville', 'The puppet show in Joyville was once a wondrous attraction until the great fire. Now, rusted gears and dark mysteries lay within strange machinations and disheveled puppets. A young boy, Simon, is the most recent in a long line of missing people. In PuppetShow: Mystery of Joyville, you are tasked with solving nefarious puzzles, finding hidden clues, and uncovering the dark secrets of a town that is anything but joyful.' FROM games WHERE igdb_id = 25926 ON CONFLICT (game_id, language_code) DO NOTHING;
