INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trigger Heart Exelica Enhanced', 'This game is an enhanced Japan-only port of the original Arcade release featuring some changes: - TH44 Faintear is now a player selectable character. - Omelette, Watt, Triggerheart Backupper C''r_na, Skiltall (also called "Skilltor"), originally only part of story concept, now appears in the game. - Other new elements include event CG, story mode and an opening movie. The opening theme is "Gravity Error" by Ayane. A limited edition includes a Nendoroid (Exelica) figure made by Good Smile Company. Pre-order also includes accessory balloon.' FROM games WHERE igdb_id = 43476 ON CONFLICT (game_id, language_code) DO NOTHING;
