INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('superstars-v8-racing', 7199, '2009-06-26', 50, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7fp3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/u0kfrjk2orh0lfafqn7i.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Superstars V8 Racing', 'Get back to 4 wheels and test your skills with V8 engines for the next racing challenge! Superstars V8 Racing is based on the license of the car racing Italian Championship that Black Bean Games has signed off with Superstars International Development. Powered by some of the most important car manufacturers in the whole world, such as BMW, Audi and Jaguar, and sporting top class production cars it delivers a breathtaking driving experience. Superstars V8 Racing offers the utmost realistic impression of the Championship. From car design to technical engine features, from the setting of the races to the turns of the tracks, everything has been designed in great detail. Every single car behaves in a complete different way accordingly to its real technical features and the settings tuned by each team competing for the title in order to get the best performance out of the powerful engine. Game play mode variety is enriched by each own cars'' peculiarity and it can be appreciated for the pick up''n play game mechanics, thought for the casual gamers, as well as for the top notch quality of the most experienced ones.' FROM games WHERE igdb_id = 7199 ON CONFLICT (game_id, language_code) DO NOTHING;
