INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('s-dot-t-a-dot-l-k-dot-e-r-dot-call-of-pripyat', 7605, '2009-10-02', 79, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa4r9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2so7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'S.T.A.L.K.E.R.: Call of Pripyat', 'The events of S.T.A.L.K.E.R.: Call of Pripyat unfold shortly after the end of S.T.A.L.K.E.R.: Shadow of Chernobyl. Having discovered about the open path to the Zone center, the government decides to hold a large-scale military "Fairway" operation aimed to take the CNPP under control. According to the operation''s plan, the first military group is to conduct an air scouting of the territory to map out the detailed layouts of anomalous fields location. Thereafter, making use of the maps, the main military forces are to be dispatched. Despite thorough preparations, the operation fails. Most of the avant-garde helicopters crash. In order to collect information on reasons behind the operation failure, Ukraine''s Security Service sends their agent into the Zone center. From now on, everything depends on you.' FROM games WHERE igdb_id = 7605 ON CONFLICT (game_id, language_code) DO NOTHING;
