INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gran Turismo', 'The highly acclaimed Gran Turismo makes its hotly anticipated debut exclusively on the PSP system, introducing the most ultra-realistic racing experience ever on a handheld. 800 cars. 35 tracks. Only possible on the PSP Prepare for the most authentic handheld racing experience as the best-selling Gran Turismo series debuts on the PSP system. Prove your driving skills on 35 tracks, and trade or share more than 800 stunning cars from the world''s top manufacturers.' FROM games WHERE igdb_id = 20426 ON CONFLICT (game_id, language_code) DO NOTHING;
