INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'GeoDefense Swarm', 'The sequel to the critically acclaimed iPhone game geoDefense. goeDefense created a whole new style of tower defense... fast, frenetic, kinetic and strategic all at the same time. And geoDefense Swarm ups the ante with even more action, and more options. With geoDefense Swarm there are no paths except for the ones you make. And you have to think ahead, because Tower placement can be critical.' FROM games WHERE igdb_id = 41499 ON CONFLICT (game_id, language_code) DO NOTHING;
