INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pentominon', 102859, '2009-08-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/ykjzrefr9qdebqkvezgy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/yy69tp1ubn9onidq40ey.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pentominon', 'A Tetris-like game with a twist: the pieces are composed of 5 blocks (hence the title "Pentominon"), and they fall in a sort of sequencer that generates hypnotic musical loops as the players progress.  To obtain higher scores the players have to delete rows in a particular way: if a single block remains "isolated" from the rest it begins to add extra points to the score in a so-called "ignition mode".  The game was developed and published in 2009 by xisai, and received an enhanced remake/sequel by the same authors in 2017 (Pentominon Transctiption, available on Xbox One).  The original version is no longer available due to the end of Xbox Live Indie Games program.' FROM games WHERE igdb_id = 102859 ON CONFLICT (game_id, language_code) DO NOTHING;
