INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oktoberfest: The Official Game', 'The official Oktoberfest game licensed by the city of Munich! Minigames Bavarian style: Finger-Wrestling, ring-the-bell strength test, ghost train, beer-serving, conducting and bavarian folk dance. Test your knowledge with the Oktoberfest Trivia Quiz and learn interesting and fun facts about the event and its history. Direct a Bavarian Humpa-Band, finger-wrestle against the mighty Sepp (the strongest man on the Oktoberfest) or catch a ride on the ghost train - a grand total of six fun and exciting minigames will help you transform yourself from a regular tourist to a proper Bavarian! Regain your strength with sausage and beer, train your brain with the Oktoberfest Trivia Quiz or just enjoy the soothing polka-soundtrack.' FROM games WHERE igdb_id = 67682 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 67682 AND p.igdb_id = 20 ON CONFLICT DO NOTHING;
