INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Teenage Mutant Ninja Turtles: Arcade Attack', 'This side-scrolling beat-em-up game is a tribute to the coin-op classics that made the Turtles video game legends. The Turtles make their return to clean up the crime-riddled streets of NYC. Shredder stands poised to take over the city - and only you can rally the might of the ninja brothers to put a stop to the threat in the present and the future...' FROM games WHERE igdb_id = 21156 ON CONFLICT (game_id, language_code) DO NOTHING;
