INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('crystal-cave-classic', 142326, '2009-09-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2o0p.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8y3z.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crystal Cave Classic', 'Crystal Cave is an adventure logic game for players of all ages.  Crystal Cave Classic is a quest for long-lost treasures buried in pitch black caves, pyramids and temples of ancient civilizations. Huge gemstones were sheltered from the sunshine for eons of time waiting for explorers brave enough to unearth them.  You - as an intrepid treasure hunter - will need all your ingenuity to pass the traps and dangers of the underground and collect the treasure in more than 170 levels.  Explore lost tombs and ancient dungeons  Lots of logic riddles - train your brain!  Play in over 170 levels  Use teleports, boulders and other types of rocks to solve levels  Four graphic scenarios  Original music  Create your own levels using our simple editor' FROM games WHERE igdb_id = 142326 ON CONFLICT (game_id, language_code) DO NOTHING;
