INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wheelman', 'The game is set in an open world environment modeled after Barcelona, full of destructible objects, alleyways, shortcuts through office blocks and a total of 31 story missions and 105 side missions. While most missions are driving-oriented, there are also foot missions which are played from a third person perspective. A wide variety of weapons are available to the player, such as pistols and RPGs.' FROM games WHERE igdb_id = 6638 ON CONFLICT (game_id, language_code) DO NOTHING;
