INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Mario RPG: The Seven Sages', 'Super Mario RPG: The Seven Sages is a Mario-series fan game created by the team ICU Gigasoft with the RPG Maker 2003 engine. The game tells about Mario, Luigi, and Bowser in a journey to obtain the powers of the legendary Seven Sages to prevent their powers from being absorbed by the mischevious Wario and Waluigi with the stolen Star Rod and use it for their greed.' FROM games WHERE igdb_id = 175832 ON CONFLICT (game_id, language_code) DO NOTHING;
