INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('air-conflicts-aces-of-world-war-ii', 3829, '2009-05-07', 57, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4nwd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scgo0q.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Air Conflicts: Aces of World War II', 'Air Conflicts is an arcade flight simulator game set in World War II, featuring the aircraft of this period and historically inspired missions. The emphasis is on intense dogfights, daring bombing raids and exciting aerial missions. 13 non-linear campaigns with more than 240 action-packed missions (patrols, manoeuvres, strategic bombing, air support, air superiority, interdiction, paratroops and supply deployment, prevent bombing missions). Authentic historical timeline and missions with focus on the gameplay. Easy control over aircraft and fun air battles.' FROM games WHERE igdb_id = 3829 ON CONFLICT (game_id, language_code) DO NOTHING;
