INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arc Rise Fantasia', 'From Image Epoch, the team that created the strategy RPG Luminous Arc, comesan epic RPG exclusively developed for the Wii. Arc Rise Fantasia is a product of old and new, combining gorgeous graphics with modern gameplay while bringing classic Japanese high fantasy role-playing action involving airships and dragons, exclusively to the platform.' FROM games WHERE igdb_id = 4678 ON CONFLICT (game_id, language_code) DO NOTHING;
