INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Build It: Miami Beach Resort', 'Build your own beach resort right where Miami began. Starting in the 1920s, every year is a new level. Build wonderful art-deco hotels, newly invented cinemas, the first fast-food diner and, decades later, giant hotels right on the beach. Design everything the way you''d like to see it over the course of 60 years on a huge scrollable map.' FROM games WHERE igdb_id = 341017 ON CONFLICT (game_id, language_code) DO NOTHING;
