INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lyra''s Melody', 'When Ralle Peregrine was a child, he began to hear a mysterious melody in his head. Around the same time, his childhood sweetheart, Lyra Shire, began to lose her hearing. As they grew up, Ralle became a guitarist to accompany the strange melody that only he hears whenever he closes his eyes. By then, Lyra had gone completely deaf. He wrote many songs for her, but she could hear none of them.' FROM games WHERE igdb_id = 191339 ON CONFLICT (game_id, language_code) DO NOTHING;
