INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nerf-n-strike-elite', 2666, '2009-10-26', 64, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9ub4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/uvfmataiwdwclozvlead.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nerf N-Strike Elite', 'Delivering a blend of covert operation elements with over-the-top blasting missions. Bundled with a newly designed blue NERF SWITCH SHOT EX-3 blaster and attachable Red Reveal decoder lens, NERF “N-Strike” Elite delivers a blend of covert operation elements with over-the-top blasting missions. Features • NERF ”N-Strike” Elite will feature a classic rail shooter style of gameplay and equip players with a cache of fresh features. • With the Wii Remote snapped into the NERF SWITCH SHOT EX-3 blaster and the Red Reveal lens engaged, players will be able to detect enemy weak spots, solve puzzles and decode secret messages as they blast their way to victory. • Customize your NERF blasters by changing the color, adding scopes, barrels and dart upgrades for tons of combinations! • All-new two-player co-op allows players to pick from four playable characters, each with their own unique blasters and abilities – plus, play with a friend to access special areas to find new blasters and other secrets. • Interact with a veritable army of enemy robots including B.O.B., the same recruiting robot from the first NERF “N-Strike” game.' FROM games WHERE igdb_id = 2666 ON CONFLICT (game_id, language_code) DO NOTHING;
