INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jumpstart Pet Rescue', 'Join the JumpStart friends on a learning adventure designed for little hands and big imaginations! The first learning game for preschoolers ever offered for Wii, JumpStart Pet Rescue is packed with over 80 fun-filled lessons and activities designed for 3-6 year olds. As players explore five worlds on a mission to rescue lost pets, they practice over 75 essential skills including pre-reading, memory, listening and more.' FROM games WHERE igdb_id = 50669 ON CONFLICT (game_id, language_code) DO NOTHING;
