INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sexy Poker', 'Get your pulse racing with a game of strip poker against a selection of six lovely manga style women. Choose the classic Texas Hold''em Poker to be thrilled as the bets increase, or try the Black Jack game mixing chance and strategy. Discover the girls'' personality: they''ll bluff you! Enter the photo gallery to see and see again the pictures you have unlocked by playing and winning. If you’re good enough, Emi, Sakura and their seductive girlfriends will bet their clothes to stay in the game!' FROM games WHERE igdb_id = 21217 ON CONFLICT (game_id, language_code) DO NOTHING;
