INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Littlest Pet Shop Friends', 'Hasbro''s best-selling miniature doll series returns to Wii with Littlest Pet Shop Friends. Collect a Great Dane, messy cat, beaver, peacock, and other potential pets while customizing them with an assortment of accessories. All of the animals are preparing for a special party, and each pet has a best friend to assist in completing the various tasks associated with the festivities. Follow your pet through town in an adventure-filled story, or choose from 12 different mini-games. You and a friend can work together to deliver party invitations, serve cake and ice cream, gather party decorations, and more.' FROM games WHERE igdb_id = 50676 ON CONFLICT (game_id, language_code) DO NOTHING;
