INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battlefield 1943', 'Using the Frostbite engine, Battlefield 1943 takes players back to WWII. The game offers hours of 24 player multiplayer action over three classic and tropic locations; Wake Island, Guadalcanal and Iwo Jima. Delivering the award-winning through-the-gun and vehicle warfare online experience DICE is best recognized for, Battlefield 1943 has players battling in ruthless aerial dog fights and intense trench combat.' FROM games WHERE igdb_id = 351 ON CONFLICT (game_id, language_code) DO NOTHING;
