INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fishdom H2O: Hidden Odyssey', 'Help Jennifer, a young marine biologist, win the Best Aquarium Award. Dive to the bottom of the sea and find various hidden items in numerous eye-teasing locations. Get cash for them to buy cute sea creatures and beautiful ornaments to create three unique aquariums. Choose from tons of accessories and supplies to make the life of your exotic swimming pets fun and comfortable. Become a genuine aquarist, polish your design skills and win trophies in this dazzling hidden object spin-off of the original Fishdom - a game by Playrix where dream aquariums come true!' FROM games WHERE igdb_id = 41486 ON CONFLICT (game_id, language_code) DO NOTHING;
