INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Impossible Quiz Book', 'The third and final installment of the Impossible Quiz series. Help Chris the cat decipher the mysteries of the Impossible Quiz Book by answering its collection of silly and non-nonsensical questions. The game is broken into 3 different chapters, the first being regularly themed, the second being themed around space and video games, and the third being focused around time travel.' FROM games WHERE igdb_id = 61549 ON CONFLICT (game_id, language_code) DO NOTHING;
