INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harry Potter: Spells', 'In Harry Potter: Spells, the player is invited to Hogwarts School of Witchcraft and Wizardry. The player will get a wand and will be Sorted in one of the four Hogwarts Houses by the Sorting Hat. There are twenty-three spells to learn in three different difficulty levels. If the player is able to do this right, he or she earns House points. If the player learns enough spells, he or she can do an online Wizard Duel.' FROM games WHERE igdb_id = 66432 ON CONFLICT (game_id, language_code) DO NOTHING;
