INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'iCarly', 'Join the cast of iCarly! Join the cast of iCarly! Their latest web show has been deleted at the last minute and you need to help them go live by creating a new show from scratch! You''ll recreate your favorite skits from iCarly and even create all-new skits with your very own backdrops, gameplay objects, music, and more. It''s a whole new iCarly experience that you can play on your own or with your friends!' FROM games WHERE igdb_id = 4921 ON CONFLICT (game_id, language_code) DO NOTHING;
