INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('buccaneer-the-pursuit-of-infamy', 25410, '2009-01-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/aghzgbuorbvdvcexucqt.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Buccaneer: The Pursuit of Infamy', 'Buccaneer is a single and multiplayer game where players strive to become the most infamous pirate captain of all time and etch their name in The Hall of Infamy.Set against a backdrop of the sunny Caribbean, players will control a variety of classic tall ships, bristling with cannons, as they plunder their way through a 50 mission campaign and go head to head against other cut-throats online.Employing a simple and intuitive control system, players will be able to jump straight into the action and begin their career in piracy.With a wide variety of non-linear single player missions and a choice of more than a dozen fully customisable ships, Buccaneer will have budding pirate captains clamouring for more!' FROM games WHERE igdb_id = 25410 ON CONFLICT (game_id, language_code) DO NOTHING;
