INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sprill & Ritchie: Adventures in Time', 'Return items to their correct era in Sprill and Ritchie - Adventures in Time, a wonderful adventure across different ages. Ritchie invites Sprill over to check out his latest invention - a time machine. When the machine is turned on, things go awry and items from all different eras of time are misplaced. Now, the young fox cub is on a thrilling adventure to restore the course of history.' FROM games WHERE igdb_id = 54420 ON CONFLICT (game_id, language_code) DO NOTHING;
