INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SaGa 2: Hihou Densetsu - Goddess of Destiny', 'SaGa 2: Hihou Densetsu - Goddess of Destiny is a role-playing video game released in 2009 for the Nintendo DS exclusively in Japan. The game is a remake of SaGa 2: Hihou Densetsu, featuring full 3D cel-shaded graphics, all new artwork by Gen Kobayashi and arranged soundtrack by Kenji Ito. This game uses a similar gameplay to the original Game Boy title, with a few quality of life improvements and new additions. Random encounters were ditched entirely, with monsters being visible on the field much like in later SaGa games.' FROM games WHERE igdb_id = 62328 ON CONFLICT (game_id, language_code) DO NOTHING;
