INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Powerbike', 'When your wheels hit the road, it''s an adrenaline rush of raw power! The dangerous world of street racing is about to get a whole lot more exciting! When an anonymous sponsor offers you resources to join the chaos, it’s time to take to the streets and show the amateurs how it’s done. Race for respect, personal pride, and cold, hard cash in the only motorcycle racer available for DS!' FROM games WHERE igdb_id = 91712 ON CONFLICT (game_id, language_code) DO NOTHING;
