INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('red-bull-x-fighters', 20629, '2009-10-22', 30, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7289.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/c6d95z9qphquopduxxc2.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Red Bull X-Fighters', 'With Red Bull X-Fighters, gamers around the world can now experience the thrill and excitement of the best Freestyle Motocross riders in the world on Xbox LIVE Arcade and PC. The game puts you, the player, on centre stage of the Red Bull X-Fighters World Tour. Take your bike, launch from huge ramps and pull off truly stunning and jaw-dropping tricks while up to 40 feet in the air. Do you have what it takes to wow the crowd and pull out all stops in the attempt to finish as overall champion? But dont expect this to be an easy challenge. Youve got to master the right level of acceleration and braking, balance your body and all the while performing death-defying maneuvers on 100-foot leaps - dont crash or it will ruin your run.' FROM games WHERE igdb_id = 20629 ON CONFLICT (game_id, language_code) DO NOTHING;
