INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-idolmaster-sp-perfect-sun', 38441, '2009-02-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2rm5.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Idolmaster: SP - Perfect Sun', 'The Idolmaster SP is a series of three Japanese raising simulation video games in The Idolmaster game series. They were released on as Perfect Sun, Missing Moon, and Wandering Star for the PlayStation Portable as a port of The Idolmaster. The gameplay in SP features changes from its predecessor, including an additional promise system which puts more of a focus on communication. The games include three game modes: two single-player and one multiplayer mode for up to three players. The story is told from the perspective of a producer in charge of training 10 prospective pop idols on their way to stardom, and each version of SP features different idols. One reason for dividing SP among three versions when developing the games was to allow players to buy the version which features their favorite idols. Rival idols were introduced into SP because the development team felt that rivals are essential for The Idolmaster, which also serve to deepen the bonds between the player and an idol. In Perfect Sun, you choose to produce one of three idols. The idols are: Haruka Amami, Makoto Kikuchi, and Yayoi Takatsuki.' FROM games WHERE igdb_id = 38441 ON CONFLICT (game_id, language_code) DO NOTHING;
