INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('railworks', 5549, '2009-06-12', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/pbotxkm3lrtiog3u2up3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sdc9z93az2fxcl8vsf1t.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Railworks', 'RailWorks, later simply Train Simulator, is a train simulation game developed by RailSimulator.com Ltd. It is the official successor to Rail Simulator, and was released online on 12 June 2009 and in stores on 3 July 2009. Compared to Rail Simulator, RailWorks contained new rolling stock, tools that previously had to be downloaded separately, graphical advancements such as modification of the existing content, bug fixes, backwards compatibility and the ability to trade elements from the virtual world with other users online. The first release of RailWorks contained all of the five real-world routes of the original European and North American releases of Rail Simulator, and added three new fictional routes: a large UK goods yard, a route set in the Alpine region and a route based around Denver, Colorado. It is a Steamworks title, which means it uses and requires Steam to activate and to deliver core game updates. Steam is also used to deliver additional routes and locomotives in the form of DLC. The core game has received several free updates since release, including major new versions RailWorks 2: Train Simulator in 2010, RailWorks 3: Train Simulator 2012 in 2011, Train Simulator 2013 in 2012 and Train Simulator 2014 in 2013.' FROM games WHERE igdb_id = 5549 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 5549 AND ge.slug = 'simulator' ON CONFLICT DO NOTHING;
