INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Charm Girls Club: My Fashion Show', 'The only club for fun, fashion and charms! It’s all about friendship, fun and collecting charms in CHARM GIRLS CLUB. Girls are immersed into the exciting world of the Charm Girls where they complete challenges that are fresh, fun and relevant to their world, collecting sparkly virtual charms along the way.' FROM games WHERE igdb_id = 68085 ON CONFLICT (game_id, language_code) DO NOTHING;
