INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World of JumpStart', 'Are your little learners ready to embark on an enchanting journey through the World of JumpStart? Invite them to create and customize their very own Jumpee, settle into a friendly neighborhood, complete exciting missions, raise magical pets and more in an interactive and adventure-filled world where knowledge is key and learning is fun. Play now to get started with Frankie and the JumpStart friends!' FROM games WHERE igdb_id = 254465 ON CONFLICT (game_id, language_code) DO NOTHING;
