INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fat Princess', 'Rescue your beloved princess through teamwork in this comic medieval battle royale. There''s a catch, though—the other team has been feeding her magical cake, making her harder to escort back to your castle. Choose from five distinct character classes and switch at any time to best help your team. Charge head first into battle, heal teammates as they break through enemy lines, and upgrade your team and the castle defenses as you work with your team to save your princess.' FROM games WHERE igdb_id = 19820 ON CONFLICT (game_id, language_code) DO NOTHING;
