INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-chronicles-of-riddick-assault-on-dark-athena', 433, '2009-04-07', 81, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8bqs.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1qr1.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Chronicles of Riddick: Assault on Dark Athena', 'The Chronicles of Riddick: Assault on Dark Athena is a new, action stealth first person shooter set in the rich, futuristic, sci-fi world of the Riddick film saga. The game features a rich storyline, intriguing, developed characters, and the voice acting of Vin Diesel. The Chronicles of Riddick: Assault on Dark Athena follows up the story from the original game title as Riddick must now flee the Dark Athena, following his harrowing escape from the notorious Butcher Bay prison. During the adventure, Richard B. Riddick must escape the predatory Merc-ship Dark Athena using stealth and action to overcome its merciless crew and challenge the nefarious Captain Revas.' FROM games WHERE igdb_id = 433 ON CONFLICT (game_id, language_code) DO NOTHING;
