INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zeno Clash', 'The innovative close combat mechanics are also a deviation from traditional action in the first-person genre that will feel fresh for new and veteran players alike. Zeno Clash is set in the punk fantasy world of Zenozoik, a land of exotic places and bizarre creatures. Players take on the role of Ghat, a man banished by his own family and forced to begin a desperate journey for survival through the forbidden desert and to the end of the world.' FROM games WHERE igdb_id = 6360 ON CONFLICT (game_id, language_code) DO NOTHING;
