INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cocoto Festival', 'Play any of the four heroes from the Cocoto saga, and discover 150 original shooting games. They are often whacky but they are always fun and they can be played by all the family! The game comes with a break-action shotgun accessory that holds the Wii Remote and Nunchuk. Shooting never was so much fun, either alone or up to four players simultaneously.' FROM games WHERE igdb_id = 50982 ON CONFLICT (game_id, language_code) DO NOTHING;
