INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Little King''s Story', '"Initially released for Wii to rave reviews, this cult classic real-time strategy game juxtaposes cutesy fairytale visuals with some decidedly adult cynicism for a zany, irreverent adventure to build, enhance, and maintain a mystical, magical kingdom. Making its way to PC for the first time, this edition of the game remains faithful to the Wii original, but brings all its charming, sassy fun to a new audience. Can you keep Alpoko safe from the Onii and help our little hero become king of the whole world?"' FROM games WHERE igdb_id = 4974 ON CONFLICT (game_id, language_code) DO NOTHING;
