INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Urban Rivals World', 'Roll up your sleeves and lay down your cards! Urban Rival is a truly original, free, collectible card game. It is a game of skill and strategy that allows you to create your own gang and challenge other players in fast and furious fighting. The games are simple but intense and in just a few minutes you can control the whole of Clint City by putting your Pillz, Fury and bluffing skills to good use!' FROM games WHERE igdb_id = 64821 ON CONFLICT (game_id, language_code) DO NOTHING;
