INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic Knight In Training', 'Sonic Knight In Training is a browser game released on the Neopets website in February 2009 to promote Sonic and the Black Knight. The player controls Sonic the Hedgehog, armed with Caliburn, in the center of an isometric corridor with crossroads pathways. The game is a reskin of Lego Star Wars II: Blaster Battle, another sponsored Neopets game previously released in 2006 to promote Lego Star Wars II: The Original Trilogy.' FROM games WHERE igdb_id = 317487 ON CONFLICT (game_id, language_code) DO NOTHING;
