INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ratchet-and-clank-a-crack-in-time-collectors-edition', 45276, '2009-11-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/zwc1yh1sedlcslgx5u9x.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ijlvwwpevjttoyrelgmn.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ratchet & Clank: A Crack in Time - Collector''s Edition', 'The collector''s edition is exclusive to PAL regions including Europe and Oceania and was released on November 6, 2009. It features the same game as Ratchet & Clank Future: A Crack in Time with some added bonus content and packaging. Includes: 3D lenticular cover art. The back has a different layout, along with a description of what the Special Edition contains. Inside is a fold-out case, that includes the manual as well as a concept art book. The fold-out case has concept art of the Great Clock. There is a picture of Alister Azimuth''s pocketwatch underneath the disc holder. The manual and concept art books have a caricature front cover design. Additions Limited edition concept art book included, which has ten pages of concept art, from A Crack in Time. There is also a code enclosed, that can unlock the discovery package for access to the Insomniac Moon through the PlayStation Network store.' FROM games WHERE igdb_id = 45276 ON CONFLICT (game_id, language_code) DO NOTHING;
