INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('diabolik-the-original-sin', 43212, '2009-06-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ofr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scf3r2.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Diabolik: The Original Sin', 'Diabolik: The Original Sin is a gritty third-person adventure game blending the heritage of the pick-and-click genre with fast-paced action sequences and minigames. The original idea of the game is based on the story created by the sisters Angela and Luciana Giussani in 1962 and its comic books. The adventure game is set in an unusual world made of a curious mix between 3D real time graphics and 2D black&white comic style animation. The traditional point-and-click genre has been perfectly adapted to the main features of the latest consoles in order to ease the developing of the main plot and minigames. The player is involved in a tricky story full of unexpected twists, intrigue, love and vengeance. In Diabolik’s skin, it won’t take too long to become a skilled thief and a master of disguise to rescue his beloved Eva. Called to be the bad guy for once, the player will find himself ensnared in fast-paced combat and stealth sequences. Diabolik is a criminal who likes luxury, expensive cars and robs to enrich himself, following his own morality. Eva, the only woman who can keep up with him, likes being involved in mysterious and complicated stories. Diabolik and Eva make up an unconventional couple; they are lovers and partners in crime.' FROM games WHERE igdb_id = 43212 ON CONFLICT (game_id, language_code) DO NOTHING;
