INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Woozworld', 'Woozworld is a social MMO based on fashion, fame, and talking to others. You can sell, buy and trade clothes, level up by doing quests, and customize your own rooms, called "Unitz", with furniture, wallpapers, and sky textures. Sometimes there are also events where you get to meet the creators or the "celebrities" of Woozworld such as Mya or Jay Wooz.' FROM games WHERE igdb_id = 92549 ON CONFLICT (game_id, language_code) DO NOTHING;
