INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('crystal-defenders-r1', 21126, '2009-01-27', 60, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5hda.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/j9uivovjcj39pvqzc0gy.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crystal Defenders R1', 'In a land ruled by might and magic, peace is ensured by the benevolent power of the crystals. In CRYSTAL DEFENDERS R1, you must deploy various units such as Soldiers and Black Mages to stop wave after wave of encroaching monsters from escaping the area with your party''s crystals. There are many different types of units to choose from, some specializing in powerful short-range attacks, some wielding far-reaching magicks, and still others equipped with bows, enabling them to bring down aerial foes. Deploy units in strategic locations to take full advantage of their traits. Each time an enemy breaches your defenses and reaches a map''s exit, your party will lose crystals. When all your crystals are gone, the game is over. CRYSTAL DEFENDERS R1 comes complete with a plethora of exciting stages, each varying in layout and difficulty. Can you defend them all without losing a single crystal?' FROM games WHERE igdb_id = 21126 ON CONFLICT (game_id, language_code) DO NOTHING;
