INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('numblast', 20282, '2009-06-18', 50, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2zho.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/h3tjztcwmsgeu4erfjdj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Numblast', 'Numblast is a colourful puzzle game which follows the tale of Japanese university students Aoyama and Akasaka. After an experiment with mysterious cubic artefacts, Aoyama accidently triggers a magic explosion that turns his colleague Akasaka into a monkey. You have to help Aoyama return his friend back to human form by solving the puzzles of Numblast. By swapping the position of the numbered cubes on a grid and creating a combination of four identical numbers in a two-by-two square, you can cause the cubes to explode. If you form longer and more complex combos the explosions become even bigger, giving you the chance of wiping out the whole board with a single combo chain - and bringing you closer to the goal of turning Akasaka back into a human. There are three modes to play outside of the main story - Endless Mode, where you must detonate as many Numblast cubes as possible until the field is completely covered by Black cubes, Time Trial Mode, which challenges you to get the highest score possible within the three minute time limit, and Puzzle Mode where you have to detonate all cubes within a predetermined number of rotations.' FROM games WHERE igdb_id = 20282 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 20282 AND ge.slug = 'puzzle' ON CONFLICT DO NOTHING;
