INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney Sing It: Pop Hits', 'Disney Sing It: Pop Hits is a video-based karaoke game that delivers the latest in pop music and lets you and your friends belt it out and have the ultimate fun singing experience. Disney Sing It: Pop Hits features hits and music videos from some of your favorite Disney stars and shows, as well as other hit artists including Taylor Swift, Jonas Brothers, Miley Cyrus, Demi Lovato, Jesse McCartney, Coldplay, and One Republic.' FROM games WHERE igdb_id = 4812 ON CONFLICT (game_id, language_code) DO NOTHING;
