INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Power', 'The Power is a platform/adventure game with the focus on exploration and action, no puzzles. It has 5 different locations on one planet, many weapons, items and upgrades. There are also plenty of boss fights and 2 different endings depending if you get all items or not. The graphics style and the game overall is simplistic but still I hope you have a good time.' FROM games WHERE igdb_id = 137071 ON CONFLICT (game_id, language_code) DO NOTHING;
