INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fast Food Panic', 'Now you can Play with your Food! Create the best restaurant in the world by cooking up yummy dishes, making your customers happy, greeting them when they stop by, and keeping your restaurant squeaky clean in this vibrant and fast-paced restaurant simulation game for Wii and DS. Keeping a top-quality restaurant takes a lot of work, and your waitress will need help-keep the place clean, make deliveries, ring up customers, and more. Special Features • Also features three difficulty levels, over 10 additional cooking mini-games, and Free Mode to replay completed levels and try for the top score.' FROM games WHERE igdb_id = 50631 ON CONFLICT (game_id, language_code) DO NOTHING;
