INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tennis Elbow Manager', 'Become a tennis coach and manage up to 4 tennis players : take care of training sessions, planning, sponsors, team members, and more ! Will you be able to lead your players to the top of the world hierarchy ? Tennis Elbow Manager features 3500 players evolving other 38 years, from 1990 to 2027, competing in more than 300 tournaments per year, both in singles and doubles !  The game was Greenlit on Steam and later released on October 14, 2016' FROM games WHERE igdb_id = 31291 ON CONFLICT (game_id, language_code) DO NOTHING;
