INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doom Resurrection', 'Doom Resurrection is an on-rails shooter survival horror game developed by Escalation Studios under leadership of John Carmack and published by id Software. It was released on 26 June 2009. The setting for Doom Resurrection is parallel to Doom 3, and it uses assets from that previously developed game.' FROM games WHERE igdb_id = 6641 ON CONFLICT (game_id, language_code) DO NOTHING;
