INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'God of War', 'A remaster of God of War, an action-adventure hack-and-slash video game developed by Santa Monica Studio and published by Sony Computer Entertainment (SCE). Loosely inspired by Greek mythology, it unfolds in ancient Greece with vengeance as its central theme. The player takes on the role of Kratos, the protagonist, a Spartan warrior devoted to the Olympian gods. Tasked by the goddess Athena, Kratos is assigned to eliminate Ares, the God of War and Kratos'' former mentor. Ares had deceitfully manipulated Kratos into killing his wife and daughter. As Ares attacks Athens fueled by hatred for Athena, Kratos embarks on a quest to locate Pandora''s Box, the sole object capable of permanently stopping the vengeful god. The remaster features full HD resolution complete with 2X anti-aliased graphics running at 60 frames per second.' FROM games WHERE igdb_id = 117883 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 117883 AND ge.slug = 'hack-and-slash-beat-em-up' ON CONFLICT DO NOTHING;
