INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Excitebots: Trick Racing', 'Excitebots is controlled with the Wii remote horizontally or optionally with the Wii Wheel. Most of the games are played on courses large in size with many opportunities to take meandering paths. The 25 different courses offered are modeled after real locations on Earth. Because of the size of each course, most races are two laps long and offer opportunities to gain massive altitude, perform various maneuvers, and obtain various items.' FROM games WHERE igdb_id = 4836 ON CONFLICT (game_id, language_code) DO NOTHING;
