INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('star-wars-the-clone-wars-republic-heroes', 210, '2009-10-06', 42, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5nrd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ps6ahjjzlngtcxywofln.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars: The Clone Wars - Republic Heroes', 'Star Wars The Clone Wars: Republic Heroes lets Star Wars fans young and old live out the sweeping galactic adventures of the Clone Wars. For the first time ever, players can fight as their favorite Jedi and clone troopers from the preeminent animated television series – from familiar faces like Anakin Skywalker to new heroes like Clone Captain Rex. A brand-new storyline, which bridges the gap between season one and two, takes the player on a multi-faceted adventure to stop a mysterious techno assassin’s destructive plot. Built around two-player cooperative action, the accessible controls and family-friendly gameplay bring Star Wars fans across generations together like never before to fight the evil Separatists and restore peace to the galaxy. Experience an all-new and exciting Clone Wars storyline that bridges the gap between season one and two of the TV series as you learn more about the mysterious bounty hunter Cad Bane and hunt down the all-new Skakoan super villain Kul Teska.' FROM games WHERE igdb_id = 210 ON CONFLICT (game_id, language_code) DO NOTHING;
