INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ninja Gaiden Sigma 2', 'Ninja Gaiden Sigma 2 is the “ultimate” Ninja Gaiden, featuring characters from the previous installments that have defined the franchise. It radiates a striking visual appeal in high resolution display, featuring character and environmental graphics whose quality exceeds the original Ninja Gaiden Sigma. Combining both melee and long-range battles against enemies, the game requires skillful and strategic playing to successfully journey through the missions.' FROM games WHERE igdb_id = 7385 ON CONFLICT (game_id, language_code) DO NOTHING;
