INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-idolmaster-sp-wandering-star', 38439, '2009-02-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2rm6.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Idolmaster: SP - Wandering Star', 'The Idolmaster SP is a series of three Japanese raising simulation video games in The Idolmaster game series. They were released on as Perfect Sun, Missing Moon, and Wandering Star for the PlayStation Portable as a port of The Idolmaster. The gameplay in SP features changes from its predecessor, including an additional promise system which puts more of a focus on communication. The games include three game modes: two single-player and one multiplayer mode for up to three players. The story is told from the perspective of a producer in charge of training 10 prospective pop idols on their way to stardom, and each version of SP features different idols. One reason for dividing SP among three versions when developing the games was to allow players to buy the version which features their favorite idols. Rival idols were introduced into SP because the development team felt that rivals are essential for The Idolmaster, which also serve to deepen the bonds between the player and an idol. In Wandering Star, you choose to produce one of three idols. (Same for the other 2 versions) The idols are: Yukiho Hagiwara, Iori Minase, Ami Futami The rival is: Takane Shijou' FROM games WHERE igdb_id = 38439 ON CONFLICT (game_id, language_code) DO NOTHING;
