INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bionic Commando', 'The first true sequel to the classic 1988 Nintendo Entertainment System original, Bionic Commando sees the return of the bionically-enhanced Nathan "R.A.D." Spencer. Time has not been kind to Spencer: Five years after his heroic defeat of the Imperials, he has been betrayed by the government he swore to serve, imprisoned for crimes he didn''t commit, and sentenced to death.' FROM games WHERE igdb_id = 6914 ON CONFLICT (game_id, language_code) DO NOTHING;
