INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mountain-sports', 50971, '2009-11-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/e9erdisnq9w3becwwcez.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scs5ig.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mountain Sports', 'Mountain Sports includes a variety of thrilling high-impact outdoor activities: skiing, snowboarding, tobogganing/tubing, bobsledding, curling and the biathlon. All of the sports except curling give players the option to hop on the Wii Balance Board for intuitive fun, carving up the slopes as they strive to become the Winter Sports Festival champion. Sit on the board to navigate the slippery bobsled course, or turn the board sideways and go for big air on the slopestyle snowboarding event! Players can also choose to use the Wii Remote to outmaneuver and blast past the competition, using full-body motion. The game is both intuitive and fun, and with four-player support, everyone can get in on the frosty action.' FROM games WHERE igdb_id = 50971 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 50971 AND ge.slug = 'sport' ON CONFLICT DO NOTHING;
