INSERT INTO game_screenshots (game_id, url, display_order, is_featured) SELECT id, 'https://images.igdb.com/igdb/image/upload/t_1080p/scs5ig.jpg', 0, true FROM games WHERE igdb_id = 50971 ON CONFLICT DO NOTHING;
