INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('wizardry-labyrinth-of-lost-souls', 21083, '2009-12-09', 65, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1y48.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arjo7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wizardry: Labyrinth of Lost Souls', 'The magic torches are lit, the monsters are ravenous, and the kingdom is waiting for a new hero. Experience the legendary Wizardry series’ modern rebirth as you traverse perilous dungeons and take on hordes of fantastic enemies. Are you up to the challenge?' FROM games WHERE igdb_id = 21083 ON CONFLICT (game_id, language_code) DO NOTHING;
