INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yakuza 3', 'Yakuza 3 is the third chapter in the Yakuza series, renowned for its authentic, gritty, and often violent look at modern Japan. Making its first appearance exclusively on the PlayStation 3 computer entertainment system, the rich story and vibrant world of Yakuza 3 let players engage in intense brutal clashes within the streets of Okinawa and the vibrant and often dangerous city of Tokyo, where only the strongest will survive.' FROM games WHERE igdb_id = 2061 ON CONFLICT (game_id, language_code) DO NOTHING;
