INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokémon SoulSilver Version', 'Pokemon HeartGold Version and Pokemon SoulSilver Version return players to the scenic Johto region first introduced in the beloved original Pokemon Gold and Pokemon Silver games nearly a decade ago. The richly detailed adventure of Pokemon Gold and Pokemon Silver is now enhanced for the Nintendo DS and Nintendo DSi systems with updated graphics and sound, as well as new touch-screen features and a host of surprises. Pokemon HeartGold Version and Pokemon SoulSilver Version bring dozens of Pokemon characters back into the limelight for a new Pokemon generation - and longtime fans - to catch, train and battle.' FROM games WHERE igdb_id = 1520 ON CONFLICT (game_id, language_code) DO NOTHING;
