INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Agatha Christie: The ABC Murders', 'Agatha Christie’s A.B.C Murders tells the story of Captain Hastings and Hercule Poirot as they attempt to solve a series of bizarre murders committed by an elusive madman. Going off the simple clue of the A.B.C railway guide left at the scene of each crime, Hastings and Poirot follow the leads to Andover, Bexhill, Churston, and Doncaster trying to apprehend the killer before the next crime is committed.' FROM games WHERE igdb_id = 19657 ON CONFLICT (game_id, language_code) DO NOTHING;
