INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NBA 2K10: Draft Combine', 'NBA 2K10: Draft Combine is a basketball simulation game. This downloadable game allows you to create an NBA prospect from the ground up. Create your own player and play through the Draft Combine in the Chicago Attack Gym. Your created player can participate in basketball drills while working with a mentor.' FROM games WHERE igdb_id = 24321 ON CONFLICT (game_id, language_code) DO NOTHING;
