INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dark-disciples-ii', 168324, '2009-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3spr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scd54g.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Disciples II', 'DD2 is, unsurprisingly, the sequel to DD1. The look and feel is therefore similar to that of the first game. However a number of significant improvements have been made to the game system: DD2 features a new story line (unconnected to that of DD1). It takes place over 4 continents and ~130 levels. The game features non linear gameplay - feel free to explore (there are tons of side missions, secret areas and off the beaten track oddities to discover). There is now a proper skill system. There are 11 skills available from Pick Locks, to Dual Weapons to Curse to Gemlore. Monster AI has also be greatly improved (DD2 uses the A* pathfinding algorithm). Monsters now have proper abilities (called ''powers''): they can shoot arrows and cast spells. Speaking of arrows, missile combat has been implemented in DD2 (there were no missile weapons in DD1). Also new is mp3 quality music (if you choose to download the ''music pack''). The level editor is more useful and much better laid out. It''s now possible to completely design your own campaign using the editor, including importing new item, tile and monster pics. A Bag of Holding has been implemented - characters can now carry twice as much once they have purchased the bag. There are also ''super'' monsters: 3x3 tiles in size!' FROM games WHERE igdb_id = 168324 ON CONFLICT (game_id, language_code) DO NOTHING;
