INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle Bears: Zombies', 'Battle Bears: Zombies is the updated edition of SkyVu''s breakout iOS hit, Battle Bears. Oliver the teddy bear is stuck behind enemy lines and has to survive unending waves of adorable Pink Bears wishing to HUG HIM TO DEATH! Armed with his trusted rifle and a whole lot of attitude, OLIVER blasts away armies of cute Huggable Bears and earns powerful weapons along the way.' FROM games WHERE igdb_id = 62329 ON CONFLICT (game_id, language_code) DO NOTHING;
