INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Plants vs. Zombies', 'Zombies are invading your home, and the only defense is your arsenal of plants! Plants vs. Zombies is a tower defense video game developed and published by PopCap Games. As a horde of zombies approaches along several parallel lanes, players must defend their homes by placing plants, which fire projectiles at the zombies or otherwise detrimentally affect them.' FROM games WHERE igdb_id = 1277 ON CONFLICT (game_id, language_code) DO NOTHING;
