INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('borderlands', 498, '2009-10-20', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co20tx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3m0q.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Borderlands', 'With its addictive action, frantic first-person shooter combat, massive arsenal of weaponry, RPG elements and four-player co-op, Borderlands is a breakthrough experience that challenges all the conventions of modern shooters. Borderlands places you in the role of a mercenary on the lawless and desolate planet of Pandora, hell-bent on finding a legendary stockpile of powerful alien technology known as The Vault. Role Playing Shooter (RPS) - combines frantic first-person shooting action with accessible role-playing character progression. Co-Op Frenzy - Fly solo in single player or drop in and out with up to 4 Player Co-Op online for a maniacal multiplayer experience. Bazillions of Guns - Gun lust fulfilled with rocket-launching shotguns, enemy-torching revolvers, SMGs that fire lightning rounds, and tons more. Radical Art Style - New visual style combines traditional rendering techniques with hand-drawn textures to create a unique and eye-catching spin on the First Person genre. Intense Vehicular Combat - Get behind the wheel and engage in intense vehicle-to-vehicle combat.' FROM games WHERE igdb_id = 498 ON CONFLICT (game_id, language_code) DO NOTHING;
