INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Fantasy XIII', 'As a deepening crisis threatens to plunge the floating world of Cocoon into chaos, a band of unsuspecting strangers find themselves branded enemies of the state. With the panicking population baying for their blood, and the military all too happy to oblige, they have no choice but to run for their lives. Join them on a desperate quest to challenge the forces controlling their fate, and prevent untold destruction. Featuring an unforgettable storyline, a battle system blending action and strategy, cutting-edge visuals and awe-inspiring cinematic sequences, FINAL FANTASY XIII delivers the next step in the evolution of gaming.' FROM games WHERE igdb_id = 389 ON CONFLICT (game_id, language_code) DO NOTHING;
