INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spectromancer', 'Open your mind and discover your power as you explore the world of Spectromancer! A turn-based online fantasy card game, co-designed by Magic: The Gathering''s Richard Garfield and Alexey Stankevich, creator of Astral Tournament and Astral Masters, Spectromancer allows players to participate in a magical duel against other mages by strategically summoning creatures and casting spells.' FROM games WHERE igdb_id = 15972 ON CONFLICT (game_id, language_code) DO NOTHING;
