INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('art-style-pictobits', 21672, '2009-01-28', 85, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5tjr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/snbww1qrhttxxsjm7xgw.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Art Style: Pictobits', 'The objective of Picopict is to move coloured blocks from the bottom of the touch screen under falling blocks of corresponding colors. If a shape is made using the added block, the blocks add to an image on the top screen. For example, if players form a red block sequence, the image will gain as many red blocks as has been cleared, assuming that the any blocks of that colour remain to be added. If blocks fall as a result of clearing blocks that were attached to it, they are added to the blocks at the bottom and can be used, though a special variety of block exists that cannot be picked up, forcing players to either clear them before they land or wait for the right blocks to fall on them. As players clear more blocks, they will eventually form an image. These images are of 8-bit renditions of characters from NES games, such as Mario, Link, and Bowser.' FROM games WHERE igdb_id = 21672 ON CONFLICT (game_id, language_code) DO NOTHING;
