INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alien Breed: Impact', 'Alien Breed Impact is an explosive science fiction arcade-shooter that resurrects a much revered franchise with an epic story, swarms of highly intelligent alien enemies, high-impact weapons, highly detailed and rich environments; all implemented with superb technology in a state-of-the-art gaming experience. In addition to the thrilling single-player campaign mode, the game also offers a relentless, action-packed, online two-player co-operative battle mode.' FROM games WHERE igdb_id = 9964 ON CONFLICT (game_id, language_code) DO NOTHING;
