INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hammerfight', 'Hammerfight is a 2D physics-based action game where you control an aircraft with your mouse. Your aircraft can be equipped with various slashing and crushing weapons, which are all effective at crushing through armor and slamming them into a wall. There are a large variety of weapons to unlock, including swords, hammers, maces, and even guns. There is an extensive campaign and arena and hunt game modes.' FROM games WHERE igdb_id = 9666 ON CONFLICT (game_id, language_code) DO NOTHING;
