INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'League of Legends', 'League of Legends is a fast-paced, competitive online game that blends the speed and intensity of an RTS with RPG elements. Two teams of powerful champions, each with a unique design and playstyle, battle head-to-head across multiple battlefields and game modes. With an ever-expanding roster of champions, frequent updates and a thriving tournament scene, League of Legends offers endless replayability for players of every skill level.' FROM games WHERE igdb_id = 115 ON CONFLICT (game_id, language_code) DO NOTHING;
