INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zombie Bowl-O-Rama', 'Bowl or Beware! From the depths of the graveyard comes a gruesome gang in search of brains! When zombies show up at the town''s lanes, it''s up to you to put ''em back in the ground! Select a colorful character to take on the attacking zombies with your favorite ball and a few tricks and treats. Give a whole new meaning to zombie strike when you set ''em up and take ''em down with cool power ups and tricky obstacles.' FROM games WHERE igdb_id = 9308 ON CONFLICT (game_id, language_code) DO NOTHING;
