INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('konung-iii-ties-of-the-dynasty', 13162, '2009-11-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co21pu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar176e.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Konung III: Ties of the Dynasty', 'Konung III is a RPG, based on the Scandinavian and Slavic mythology, the third game in the Konung series (Konung: Legends of the North and Konung 2: Blood of Titans). The new game brings the player back to the legendary Woodland – the unique and spacious fantasy land that combines parts of known history with classical myths of the Slavs, the Scandinavian and the Byzantine, as well as the legends of the Chronicles, including immortal heroes, magical artifacts and ancient sorcery world. The Era of Titans, the almighty rulers of the Earth, has ended. Once glorious heroes and great Princes are gone for good. The hour of new heroes has come, when the throne of the Grand Principality became empty.' FROM games WHERE igdb_id = 13162 ON CONFLICT (game_id, language_code) DO NOTHING;
