INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('metal-drift', 14957, '2009-09-04', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/zyjk4rhq8oc21bnnev5f.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/bmom6vjn12imvpzbtwkd.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metal Drift', 'Metal Drift is a vehicular sport combat game set in a distant future. As the player, you command an agile, high powered hover tank in a futuristic sports arena. Core game play centers on intense tank-on-tank multiplayer team combat seen through an immersive, first person cockpit.  Layered on this is a goal-oriented game type that allows for high level strategy and team dynamics. Players can level up to unlock new ranks, weapons, and upgrades.Each weapon and upgrade is specifically designed and balanced to allow different styles of play.    Pair up the Stealth upgrade and the Shock Cannon to uncloak behind an enemy player and unload a devastating blow before disappearing again.  Or choose the Sensor upgrade to see where all the nearby players are, and the Temporal Cannon to shoot them through walls!  There are 56 possible combinations – choose whichever suits your strategy.' FROM games WHERE igdb_id = 14957 ON CONFLICT (game_id, language_code) DO NOTHING;
