INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jade Wolf', 'Jade Wolf is a platformer game created and developed by Sedition Games in March 2009. In this game, the player controls the titular white wolf venturing in a world inspired and based on Chiang Mai and Thailand, where the creator lives. The gameplay is largely inspired by Sonic The Hedgehog, as well as the Zelda games to a lesser extent. The player must collect 12 Jade Ornaments, and use their power to send the Standing Apes back to the ancient city from whence they came.' FROM games WHERE igdb_id = 197899 ON CONFLICT (game_id, language_code) DO NOTHING;
