INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SingStar: Made in Germany', 'SingStar: Made in Germany is a karaoke game exclusively released in Germany. It exclusively features songs by German (respectively German produced) artists. There are no changes to the gameplay formula: player(s) sing into a microphone and the game gives points based on the performance. The only basis of assessment is if the correct note is hit with the correct timeing; the sung words or octave does not play into the result.' FROM games WHERE igdb_id = 103023 ON CONFLICT (game_id, language_code) DO NOTHING;
