INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gerbil Physics', 'Gerbils have been imprisoned in blocks by the evil Toad King and turned into stacked monuments. The stacks must be knocked down in order to free the gerbils. In each level, the players uses a limited number of bombs, blasts, nukes or ropes to launch the gerbils beneath the level line. Additional points are awarded for using less resources than provided and for knocking down as many gerbils in a short amount of time. Gerbils in red blocks must never be touched.' FROM games WHERE igdb_id = 93524 ON CONFLICT (game_id, language_code) DO NOTHING;
