INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heroes of Hellas 2: Olympia', 'Restore a failing civilization with wisdom and justice in Heroes of Hellas 2, a captivating sequel full of challenge and surprises! Shape it and its people by providing the resources to create a citadel of light, in a kingdom of darkness. Recover the Rod of Discord and vanquish the evil demon!' FROM games WHERE igdb_id = 54096 ON CONFLICT (game_id, language_code) DO NOTHING;
