INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wonderworld Amusement Park', 'All of the fun and thrills of your favorite amusement parks and carnivals have gone portable! In Wonder World Amusement Park for DS, the complete day-at-the-park experience is in your hands with 6 themed zones full of mini games and an exhilarating ride in each. Play through a huge variety of mini-games as you win outfits and prizes for your unique character. Step right up and test your skills in a fun filled experience for the whole family!' FROM games WHERE igdb_id = 47968 ON CONFLICT (game_id, language_code) DO NOTHING;
