INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gamerbots: Third-Robot Shooting', 'An exciting LIVE third-person shooter where you can: Stick your Gamer Picture on Gamerbot; Customize your Gamerbot with 15 heads and unlimited color combinations; Fight with 6 basic weapons and 10 levels of upgrade in 4 criteria; Compete with worldwide players on LIVE; Challenge to 24 single player missions; Get promoted to 7 Gamerbot classes; Fight with random enemies in 6 scenes.' FROM games WHERE igdb_id = 144036 ON CONFLICT (game_id, language_code) DO NOTHING;
