INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Downfall', 'Quiet Haven Hotel was supposed to be just a one night shelter for Joe and Lucy Davis. But things soon start to go wrong. Lucy''s panic attacks get worse and soon she disappears. And in the morning, the hotel changes too. Nothing is what it seems anymore. Joe is left alone, trying to understand what is happening, trapped between reality and this nightmare.' FROM games WHERE igdb_id = 213124 ON CONFLICT (game_id, language_code) DO NOTHING;
