INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Overlord: Dark Legend', 'Dark Legend is a spinoff of the 2007 video game Overlord, and is set as a prequel. The gameplay is similar to Overlord, but presents some differences. While the game does not have several features of the original game or its sequel, Overlord II, it offers some new content and a new gameplay style taking advantage of the Wii controller. Reviews of the game are mixed: praising the humour, story, and controls of the game, but finding problems with the animation, short game length, and lack of complexity or difficulty.' FROM games WHERE igdb_id = 47 ON CONFLICT (game_id, language_code) DO NOTHING;
