INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Squirm', 'This is a DS port of Squirm, a PacMan style arcade game, from Commodore 16. It reuses all original graphics, in attempts to remain as faithful as possible to the original version. Navigate around the maze while steering clear of the Squirms. You need to find and eat 200 eggs laid by the Queen Squirm. And like PacMan, if a squirm gets to you, then you will be back to the start.' FROM games WHERE igdb_id = 298947 ON CONFLICT (game_id, language_code) DO NOTHING;
