INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chaser', 'Developed over a couple of days, Chaser is not what it first appears to be. Players are presented with a simple black environment and take control of a green man chasing a turquoise figure. Over time, you’ll pick up speed, grab coins that the turquoise man throws out, and eventually trip and come to a standstill.' FROM games WHERE igdb_id = 242694 ON CONFLICT (game_id, language_code) DO NOTHING;
