INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hajikise!', 'Released in 2009, Hajikise! is a turn-based RPG for Windows PC. It was developed and released by Hachimitsu Kumasan, a doujin game developer. Hajikise! is a traditional Japanese RPG that uses two-dimensional top-down view. Characters can be customized from a number of different classes and their skills.' FROM games WHERE igdb_id = 265155 ON CONFLICT (game_id, language_code) DO NOTHING;
