INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Diva Girls: Divas on Ice', 'Meet the Diva Girls for the first time on Nintendo Wii. Everyone''s got their favorite but who will be yours? Kelly, Gabrielle, Alyssa and Madison are four young girls skating for glory in the Miracle Ice Festival. Dress your favorite Diva Girl in thousands of combinations of customizable outfits then train hard to upgrade your skating skills so you can woo the crowd, impress the judges and be crowned Princess on Ice.' FROM games WHERE igdb_id = 51035 ON CONFLICT (game_id, language_code) DO NOTHING;
