INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wizard''s Hat', 'Clean up the Magic Glades using your amazing match-three abilities!  To play, simply move a Wizard''s Hat along the bottom of your screen, click to grab objects from above and then click again to launch the objects back at the descending rows. Once you start piecing together outrageous combos, you won''t want to stop!  Just remember to plan your moves well so you can create huge chain reactions and earn enough money to purchase awesome upgrades like the Magnificent Magic Wand and the Shiny Cauldron.' FROM games WHERE igdb_id = 25271 ON CONFLICT (game_id, language_code) DO NOTHING;
