INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harvest: Massive Encounter', 'Harvest: Massive Encounter is an award-winning real-time strategy game with battles of epic proportions and a unique style of resource management and exploration. Build power plants, mineral harvesters and defense towers and make sure they have sufficient energy to fend off endless hordes of evil aliens. The game offers a vast array of possible strategies with these simple rules, and will compel you to try new and better base designs every time.' FROM games WHERE igdb_id = 15936 ON CONFLICT (game_id, language_code) DO NOTHING;
