INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mind Body & Soul: Big Word Puzzle Book', 's your brain ready for a big challenge? Big Word Puzzle Book is a collection of letter-based puzzles, both familiar and new. Use the Nintendo DS stylus to tackle eight different teasers and, if you''re ever a little stuck, a helpful hint system is on-hand. So whether it''s a quick round of ''hangman'' or a crafty wordsearch, there''s always a fresh challenge waiting for you.' FROM games WHERE igdb_id = 92626 ON CONFLICT (game_id, language_code) DO NOTHING;
