INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Resident Evil 5: Steelbook Edition', 'Chris Redfield returns to the series as the main character in Resident Evil 5, a game which takes place five years after Resident Evil 4. He is sent to Kijuju, Africa, where local agent Sheva Alomar joins him in the mission to apprehend Ricardo Irwing, who is trying to sell bio-weapons in the black market. Soon they are attacked by hordes of locals infected by an improved version of the "las plagas" parasite seen in Resident Evil 4, which they call "majini". As the story progresses, Chris discovers that some old fellows are behind the whole incident.' FROM games WHERE igdb_id = 110408 ON CONFLICT (game_id, language_code) DO NOTHING;
