INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doc Louis''s Punch-Out!!', 'It''s Little Mac vs. Doc Louis!! Step into Little Mac''s shoes and challenge your mentor and coach, Doc Louis, to prove you have what it takes to become the World Video Boxing Association World Champion. This unique one-on-one bout builds off of the fun and excitement found in the retail version of Punch-Out!! for the Wii console.' FROM games WHERE igdb_id = 9153 ON CONFLICT (game_id, language_code) DO NOTHING;
