INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Nebula: Episode One', 'Dark Nebula is a skill-based action game where the objective is to get your player character through an array of levels filled with various obstacles. The controls are similar to marble labyrinth games but the levels are filled with elements and puzzles inspired by platform games where you need to jump over swinging blades, dodge spikes and avoid deadly falls.' FROM games WHERE igdb_id = 67242 ON CONFLICT (game_id, language_code) DO NOTHING;
