INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gyakuten Vocaloid', 'A very serious crime has taken place in the Vocaloid world and only a top lawyer can find the truth and that lawyer is... wait... Hatsune Miku!? Exactly! Put yourself in the shoes of Miku to solve the case that looms over the court in this fan-game full of tension and ideal comedy for lovers of Ace Attorney and Vocaloid, discover the truth behind the contradictions in the testimonials and prove that your client is innocent!' FROM games WHERE igdb_id = 296162 ON CONFLICT (game_id, language_code) DO NOTHING;
