INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeon Scroll', 'If a word game and a dungeon crawler had a baby, this would be it. Arrange tiles to create magic words and blast rats, spiders and skeletons. But beware, a great evil looms beneath the depths. Grab your wand and sharpen your intellect for you’re about to embark on a dangerous journey through twenty-five of the most vile dungeons in the realm!' FROM games WHERE igdb_id = 174314 ON CONFLICT (game_id, language_code) DO NOTHING;
