INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Taisho Yakyuu Musume: Otometachi no Seishun Nikki', 'Koume is a girls'' high school student. One day, Akiko, her close friend, suddenly says to Koume, "I would like you to play baseball with me!" Koume accepts her offer, but can they collect nine players? What do they need first? How about the rules? Will they be able to win against a boys'' team...?' FROM games WHERE igdb_id = 269515 ON CONFLICT (game_id, language_code) DO NOTHING;
