INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Moron Test', 'Graduate from Moron to Genius as you tap, twist, and shake your way through these fun and tricky mind challenges. The tricky puzzles include questions that test your memory, reading comprehension, math, patience, problem solving and more! No two questions are exactly alike, but they’re all made to boggle the mind.' FROM games WHERE igdb_id = 117757 ON CONFLICT (game_id, language_code) DO NOTHING;
