INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MadWorld', '"MadWorld is a unique action game experience with two signature characteristics: An eye-catching, monochromatic visual style that’s yet to be matched; and sense-shattering, bone-shredding violence. Experience a unique blend of brutality, humor and madness in a graphic novel-style world that’s black and white and blood-red all over. In sharp contrast to what you’ve come to expect on the Wii, MadWorld was available in American and European markets almost a full year before it was finally allowed in Japan."' FROM games WHERE igdb_id = 3214 ON CONFLICT (game_id, language_code) DO NOTHING;
