INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hero''s Realm', 'Lead four heroes and their teams against the evil forces of Mephistocles, the Lord of Demons in this retro-RPG adventure. Toggle between the four heroes as you explore dungeons, ascend towers, spelunk caves, save villages and defeat the forces of evil! Reminiscent of classic RPGs such as Dragon Quest III and Final Fantasy V, Hero''s Realm is a fun romp in old-school RPG nostalgia.' FROM games WHERE igdb_id = 122883 ON CONFLICT (game_id, language_code) DO NOTHING;
