INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jigsaw World', 'Open up a world of puzzles and slip away to soothing jigsaw fun with Jigsaw World. Assemble your choice of 60 fantastic puzzles from six original themes. Put together incredible images of vivid flowers, stunning landscapes, majestic animals and more. Featuring easy-to-use controls, rich full-screen graphics, and endless possibilities, Jigsaw World is a wonderful escape.' FROM games WHERE igdb_id = 80812 ON CONFLICT (game_id, language_code) DO NOTHING;
