INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('itzazoo', 16109, '2009-11-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/njdlryhsgx74ec3xevs0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/pbqfxxxuomewxbekfd5d.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ItzaZoo', 'Children jump right into a drawing adventure with friendly animals that are ready to play and help them learn to read!  Using Living Ink – Sabi’s unique drawing recognition system - kid''s drawings become one-of-a kind interactive objects that form the centerpiece of the game''s action.   Crafted especially for early-readers, the game play is designed to provide a new way for children to practice reading and creative problem solving skills. New methods to engage children in learning, discovered during a multi-year research project conducted by Microsoft Corporation, are fused into the game''s design, yielding a unique experience that enhances self-confidence and encourages fun and learning. The game provides a totally unique experience every time it is played. Since the environment is created through each player''s personal drawings, the possibilities are as endless and fantastic as your child''s imagination.' FROM games WHERE igdb_id = 16109 ON CONFLICT (game_id, language_code) DO NOTHING;
