INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pixel Ranger', 'The evil aliens took away everything the Pixel Ranger ever loved. So now, as long as there is a single pixel left in him, he will fight the vicious extraterrestrials. It’s your job to guide the Pixel Ranger as he shoots his way through hordes of alien invaders. Aim carefully, dodge their lasers and blast them to pixels!' FROM games WHERE igdb_id = 239940 ON CONFLICT (game_id, language_code) DO NOTHING;
