INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dance Party: Club Hits', 'The Dance Party games feature music from two different genres to appeal to a broad audience, including classic tracks from leading artists like "Black and Gold" - Sam Sparro, "The Creeps" - Camille Jones, "Cry For You" - September, "Push The Button" - Sugababes, "Some Kinda Rush" - Booty Luv and "Murder On The Dance Floor" by Sophie Ellis Bextor.' FROM games WHERE igdb_id = 50928 ON CONFLICT (game_id, language_code) DO NOTHING;
