INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'AFL Mascot Manor', 'It''s all about team spirit! Choose between 16 team mascots, each with their own superpowers! Explore and conquer 48 fantasy environments using your Super Abilities! Battle your enemies using Fiery Fists and Ground Smash, or unleash your mascot''s special attack! Face off against other team mascots in an epic boss-battle clash. Find, collect, and trade AFL player cards to boost your team in the mini-match. Fun mini games including an unlockable AFL mini-match.' FROM games WHERE igdb_id = 91707 ON CONFLICT (game_id, language_code) DO NOTHING;
