INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harbor Master', 'Harbor Master is a mobile strategy and time management game. Players manage a harbor by guiding ships to docks, unloading cargo, and preventing collisions. The game involves drawing paths for ships to navigate safely, with increasing difficulty as more ships enter the harbor simultaneously. Players earn points by efficiently directing ships and avoiding crashes.' FROM games WHERE igdb_id = 67604 ON CONFLICT (game_id, language_code) DO NOTHING;
