INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Escape It!', 'Escape It is a homebrew Atari 2600 game developed by Alan W. Smith and released in 2011. The game was later included in the Atari Flashback series of plug-and-play consoles, starting with the Atari Flashback 5 in 2014, and most recently in the Atari Flashback X Deluxe in 2019. In Escape It, two players must move their squares through a procedurally-generated maze, the layout of which completely regenerates around once per second. The first player to successfully navigate from the bottom-left corner of the screen to the exit at the top-right corner is the winner.' FROM games WHERE igdb_id = 283621 ON CONFLICT (game_id, language_code) DO NOTHING;
