INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jewel Quest Solitaire 1', 'Play Tripeaks Solitaire in a new way using jewel-themed decks. Match card suits to earn pieces for the jewel board then turn the board''s spaces to gold. Unearth buried cards, avoid cursed jewels and solve the 114 card layouts on a South American jungle trek. Experience 684 possible card scenarios through an exciting new Jewel Quest story. Embark on your card playing adventure in ''Jewel Quest Solitaire''!' FROM games WHERE igdb_id = 10475 ON CONFLICT (game_id, language_code) DO NOTHING;
