INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('disneys-a-christmas-carol', 21086, '2009-11-03', 60, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1w16.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/pb28zh7mtvmeniescwaw.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s A Christmas Carol', 'Inspired by the Dickens tale re-imagined by Robert Zemeckis, Disneys A Christmas Carol is an innovative puzzle-adventure game celebrating the spirit of the holidays with a Scrooge twist. The game invites a new generation to connect with the illustrious story & characters like never before and is sure to become a tradition embraced by the whole family. This keepsake from the movie will provide hours of festive entertainment and is destined to be an instant classic. Features Manipulate Scrooges environments to guide him on his supernatural adventure Blow and shout into the microphone and use the DS stylus to pull, shake, drag, rattle and tap Scrooges world and influence game play Experience immersive animated cutscenes that unfold like an interactive story book with amazing beauty and detail Interact with your favorite characters from the film, including Bob Cratchit, Tiny Tim, Mr Fezziwig, Marley and the three spirits of Christmas Use the real-time advent calendar to unlock surprises for everyday that you play leading up to Christmas Sing carols, decorate with holiday ornaments, and cook recipes from the Victorian era Master over 10 single-player mini-games, plus join a friend for a pass the DS multiplayer game' FROM games WHERE igdb_id = 21086 ON CONFLICT (game_id, language_code) DO NOTHING;
