INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Choose Your Weapons TD', 'This game combines the game play of a tower defense game, and the fun of destroying the stickman virus. You get to use towers, and some fun things to lay on the track (mouse trap, land mines, frying pan). They all eliminate the virus in their own fun way.' FROM games WHERE igdb_id = 234718 ON CONFLICT (game_id, language_code) DO NOTHING;
