INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jean''s Boutique', 'Run your own Jean''s Boutique, a great fashion game combined with the fun of serving customers. To make it in the fast-paced world of fashion, Jean will need to be fast on her feet, dedicated to her customers, wise in her upgrades. For fast fashion fun, there''s no place like Jean''s Boutique!' FROM games WHERE igdb_id = 197028 ON CONFLICT (game_id, language_code) DO NOTHING;
