INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battleship', 'In Battleship, two players place 5 ships onto a grid hidden from their opponent. Each player then selects one of their opponents grid coordinates to attack. If part of an opponent ship is on that grid coordinate, it takes a hit. Once all the spaces a ship occupies have been hit, the ship sinks. Sink all of your opponent''s ships and you win.' FROM games WHERE igdb_id = 95434 ON CONFLICT (game_id, language_code) DO NOTHING;
