INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The General', 'In this version of the classic board game you lead your troops into battle against the computer opponent in a race to capture your enemy''s flag before he gets yours. Initially you can''t see how the enemy has positioned his troops and he can''t see yours which gives ample opportunity for bluffing and deception from both sides.' FROM games WHERE igdb_id = 174369 ON CONFLICT (game_id, language_code) DO NOTHING;
