INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heavy Metal Thunder', 'The game pits futuristic robots against one another in wrestling matches. The player controls a robot during battles using a four-icon menu. Three actions—strike, guard and grapple—can be executed at any time and augments the player''s "beat meter".' FROM games WHERE igdb_id = 56142 ON CONFLICT (game_id, language_code) DO NOTHING;
