INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Geon Cube', 'Grab your cube in Geon Cube a psychedelic, pick-up-and-play action puzzle game of rapidly changing tactics, bright colors, power ups and frenzied speed to see who is the undisputed Geon master! Frantically race against your opponents playing as one of eight Geon emotion cubes as you collect pellets and score goals, while preventing them from doing the same! Utilize unique power ups as you go back, forward.' FROM games WHERE igdb_id = 50636 ON CONFLICT (game_id, language_code) DO NOTHING;
