INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Age of Pahlevans', 'The plotline of Age of Heroes, derived from Ferdowsi''s epic the Shahnameh, centers on the efforts of Atar, son of Pishad and commander of the kingdom of Sistan, to fight against demons which have captured and laid waste to much of the region. The game features 110 mythical figures (including Arash, Siavash, Fereidun, Kaveh, Esfandiar, Rustam, and Zal) living in nine regions (including Sistan, Sarsabz, Kuhestan, and Atashfeshani)' FROM games WHERE igdb_id = 191670 ON CONFLICT (game_id, language_code) DO NOTHING;
