INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Guitar Star', 'A plug-and-play console designed to capitalize on the boom of games like Guitar Hero and Rock Band, manufactured and released sometime in 2009. It contains licensed MIDI versions of various rock songs like ''Dream Police'' (Cheap Trick) and ''Thriller'' (Fall Out Boy), and four modes from which to play them in. It has garnered a reputation for being a rather poor representation of the ''guitar game'' subtype, often pointing to the lackluster covers and low production quality.' FROM games WHERE igdb_id = 267958 ON CONFLICT (game_id, language_code) DO NOTHING;
