INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'FootballTeam', 'Create your footballer, control your line up and play with friends & other live players Worldwide in a desktop computer or a mobile device browser (iOS/Android); Take full control: join the Club or become a Manager; train your Footballer or your Squad; Play or Bid - all aspects of the game are up to you; A Classical 2D presentation of the football games, with many unexpected changes on the field, as well as commentaries "live", ensure Every Game is Fun; An Active Participation of both a Manager and his Teammates determines the triumph or fiasco of each match - this is more than a Football Manager Game; A Soccer Manager at its truest form, where the career of your Footballer, Team Tactics, as well as the success of each game (or maybe even a Football Team as a whole) are in your hands!' FROM games WHERE igdb_id = 153801 ON CONFLICT (game_id, language_code) DO NOTHING;
