INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dengeki Gakuen RPG: Cross of Venus', 'The player assumes the role of an unnamed protagonist attending Dengeki Academy who stumbles into a fight between heroines from Dengeki Bunko novel worlds and the evil organization Zetsumu. The reality-based world of Dengeki Academy and the novel worlds have become connected and the player is able to help the Dengeki Bunko heroines fight the Zetsumu by going between the worlds. Eight heroines are presented including Shana from Shakugan no Shana, Kino from Kino''s Journey, and Kana Iriya from Iriya no Sora, UFO no Natsu. Each heroine fights with her own unique style of weapon, combos, and special attacks.' FROM games WHERE igdb_id = 70697 ON CONFLICT (game_id, language_code) DO NOTHING;
