INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'V is for Vortex', 'V is for Vortex is a simple but addicting puzzle game. After waking up in a strange testing facility you find yourself thrust into a series of bizarre tests with only your wits, and a strange gun by your side. V is for Vortex ships with 18 fun levels that will challenge your mind and bend the rules of space. Can you beat every level?' FROM games WHERE igdb_id = 254474 ON CONFLICT (game_id, language_code) DO NOTHING;
