INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Knight of the Living Dead', 'Camelot is being overrun by zombie knights, and only the brave Sir Galahad can hold them back and restore peace to the kingdom. Knight of the Living Dead is an action-packed arena slasher with constant waves of the undead that need to be slayed quickly.' FROM games WHERE igdb_id = 242733 ON CONFLICT (game_id, language_code) DO NOTHING;
