INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Go! Underground', 'Go! Underground (or Journey to the Center of the Earth) takes a player into the depths of the Earth to explore subterranean environments and collect relics. A treasure map gives hints as to the location of each relic, and your task is to unlock a variety of paths and find all 40.' FROM games WHERE igdb_id = 242728 ON CONFLICT (game_id, language_code) DO NOTHING;
