INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kingdom Hearts Magical Puzzle Clash', 'Kingdom Hearts Magical Puzzle Clash, stylized as Kingdom Hearts 358/2 Days Magical Puzzle Clash, was an online flash game released to the Disney website by Square Enix and Disney. It has since been discontinued and is no longer officially accessible. The game was made to promote Kingdom Hearts 358/2 Days and is not canon to the series in any way.' FROM games WHERE igdb_id = 303861 ON CONFLICT (game_id, language_code) DO NOTHING;
