INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dream Day: Wedding Destinations', 'Dream Day Wedding Destinations delivers a romantic adventure filled with hidden treasures, excitement and the inevitable wedding crisis! It is up to you to create a dream wedding for three happy brides. As the wedding planner you must find all the necessary hidden items as you visit the florist, bridal shop, bakery and more to make her big day a fairytale. Experience pure bliss with Dream Day Wedding Destinations!' FROM games WHERE igdb_id = 47781 ON CONFLICT (game_id, language_code) DO NOTHING;
