INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('star-trek-d-a-c', 21195, '2009-10-06', 50, 'https://images.igdb.com/igdb/image/upload/t_cover_big/aseethrarhp0ioieb0m9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc82ji.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Trek: D-A-C', 'Star Trek: D-A-C allows fans to directly control a variety of ships and pitch battles between Starfleet and the Romulan Empire. Up to 12 players can compete in thrilling team combat. There are three game play modes - single player, online multiplayer and online co-op. For each mode, there are three different game types - Team DeathMatch, Assault and Conquest. Players can choose from three ship types for each faction, including the newfeatured in the "Star Trek" film. Each ship - the powerful Flagship, the nimble Fighter and the devastating Bomber - offers its own unique capabilities for players to master and manipulate as they fight for victory. In addition to featuring the new U.S.S. Enterprise, Star Trek: D-A-C incorporates music and signature sounds taken directly from the new "Star Trek" film.' FROM games WHERE igdb_id = 21195 ON CONFLICT (game_id, language_code) DO NOTHING;
