INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'We Cheer 2', 'Get ready to shake your pom-poms and show your team spirit with the newest version of the hit cheerleading game! We Cheer 2 uses your Wii Remote(s) as pom-poms as you perform fullbody motions to hit music of the past and present. This new installment includes all new challenging dance moves, new stages, modes of play, outfits and more! With various single and multiplayer modes, you''ll need to bring your energy and your rhythm if you want to master these moves!' FROM games WHERE igdb_id = 5264 ON CONFLICT (game_id, language_code) DO NOTHING;
