INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'We Wish You a Merry Christmas', 'With seven gameplay modes and 5 Holiday-themed activities, We Wish You a Merry Christmas includes games like Elf Bowling, Present Catch, Reindeer Races and more! Race to deliver presents by the end of the night in "Santa''s Sleigh," Serve thirsty elves in "Hot, Hot Chocolate", match three of the same decorations to clear the board in "Deck the Halls." The Holiday spirit doesn''t end when you’re done playing! Count down the days to Christmas in the included Advent Calendar. Turn your television into a fireplace with the burning "Yule Log" feature and lead your family in beloved Christmas Carols with the "Holiday Sing-a-Long" mode. Use the pop-up keyboard to write a letter to Santa and you may even get a response!' FROM games WHERE igdb_id = 5277 ON CONFLICT (game_id, language_code) DO NOTHING;
