INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ping Pong!', 'Ping Pong! is a simulation of table tennis, with one-player and two-player mode. In one-player mode, the player takes on four ping pong champs in a row; the two-player mode allows a single match. There are five different hits, which subtly change the speed and trajectory of the ball. Hitting the ball seven times in a row allows you to execute a "super smash".' FROM games WHERE igdb_id = 199152 ON CONFLICT (game_id, language_code) DO NOTHING;
