INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Treasure Grab', 'Become a master thief and prove your skills on the path of misdeeds! Choose your targets, confuse guards, pick locks, annoy nobles, and steal everything that has not been nailed down! Jewels, paintings, tableware, paintings and cakes, it''s all worth stuffing into your sack. And in a pinch, summon the Trickster Spirits to don on a disguise, slow down time or turn invisible to confuse the guards! The night is yours - it''s up to you to decide how to rule it.' FROM games WHERE igdb_id = 199198 ON CONFLICT (game_id, language_code) DO NOTHING;
