INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rubber Ninjas', 'Rubber Ninjas is an experimental 3D ragdoll fighting game by Matteo Guarnieri of Rag Doll Software. The game features ragdolls of many sizes and shapes, fighting bare handed or with a variety of different weapons. Thanks to the innovative gameplay based on Matteo''s own Ragdoll Masters, players will never fight the same fight twice, and all moves will be different and spectacular.' FROM games WHERE igdb_id = 75143 ON CONFLICT (game_id, language_code) DO NOTHING;
