INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pixeljunk-monsters-deluxe', 44520, '2009-10-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2nyw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8nry.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PixelJunk Monsters Deluxe', 'In PixelJunk Monsters Deluxe, the player controls a defender-of-the-forest character in a lush 2D environment. The player''s goal is to strategically defend the pathway to his home base from an onslaught of various threatening monsters. In between waves of monster attacks, the player scrambles to reinforce his defenses by collecting gold coins and jewels from fallen enemies to finance new towers and research deadlier weapons. The game features a new island with more than 10 stages, new enemies, music tracks and special bonus features. With two new unique towers available, players can enjoy all the original Monster stages with fresh new gameplay. Creator Dylan Cuthbert described PixelJunk Monsters Deluxe as the "ultimate version" of the game. It contains all of the level content from the original game and its Encore expansion pack, as well as new levels, enemies, and towers. Additional music, videos, concept art, and other special features are also included.' FROM games WHERE igdb_id = 44520 ON CONFLICT (game_id, language_code) DO NOTHING;
