INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Armalyte: Competition Edition', 'Armalyte: Competition Edition is available for the first time ever as a proper C64 commercial release! One of the best shoot ''em ups ever to be released on the C64 featuring eight levels of frantic shoot ''em up action, requiring nerves of steel and a sharp eye for the invading forces. With stunning and original graphics, animation and tracks of superlative music and sound FX. The Competition Edition features level-select, adjustable enemy bullet speeds, scrolling demo mode + more!' FROM games WHERE igdb_id = 299486 ON CONFLICT (game_id, language_code) DO NOTHING;
