INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Luxor: Mah Jong', 'Embark on an epic quest to recover the stolen treasures of Ancient Egypt in LUXOR: Mah Jong. The fun and challenge is unending with 200 unique layouts available in 3 awesome play modes; Adventure, Single and Traditional. Three difficulty settings ensure that any player will find a challenge, and 3 exotic tile sets make LUXOR: Mah Jong a truly custom experience. Can you work your way up from a lowly farm hand to become the Pharaoh of all Egypt' FROM games WHERE igdb_id = 16004 ON CONFLICT (game_id, language_code) DO NOTHING;
