INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jelly Belly: Ballistic Beans', 'A fast-paced arcade style game of skill, Jelly Belly Ballistic Beans! combines simple but highly addictive gameplay with a world-recognized license to provide a gaming experience that will appeal to casual players as well as seasoned veterans. Try your hand at hundreds of puzzles across 8 different themes. Simple to pick up, but impossible to put down! The main objective is to get the required number of Jelly Belly Beans into the matching cups while scoring points, using power-ups, and earning bonuses along the way. Players use the bean launcher to propel the beans through intricate puzzle patterns. Exploding beans, rocket beans, and extra beans are just some of the power-ups to help players beat the puzzle quickly to score medals.' FROM games WHERE igdb_id = 43396 ON CONFLICT (game_id, language_code) DO NOTHING;
