INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Clay Hunt', 'Can''t make it to the range and have an itch to bust some clays? Accurate touch controls and real physics makes Clay Hunt an authentic shotgun shooting experience. In five different game modes you''ll have to learn to handle a shotgun like an expert and hit rapidly flying targets from varying angles! Including Arcade Challenge featuring upgrades, power-ups and unlimited gameplay.' FROM games WHERE igdb_id = 175235 ON CONFLICT (game_id, language_code) DO NOTHING;
