INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Trek: The Mobile Game', 'The Mobile Game is a tie-in game based on the adventures of the USS Enterprise''s crew in the alternate reality created by Nero''s incursion. The game involves traveling through Klingon, Cardassian and Romulan space, fighting enemies while trying to keep the starship going as long as possible.' FROM games WHERE igdb_id = 125127 ON CONFLICT (game_id, language_code) DO NOTHING;
