INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yumsters 2: Around the World', 'Not only are these Yumsters crazy for strawberries, they can rock the bongos. For the love of fruity music, help them earn money by cleaning gardens to promote their band. To really skyrocket, Yumsters need the best equipment to win the ultimate grand prize at the fairy town music showdown. Get fruitilicious in five vibrant locations of Yumsters 2, a sweet Match 3 puzzler.' FROM games WHERE igdb_id = 14950 ON CONFLICT (game_id, language_code) DO NOTHING;
