INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Echoes', 'Delve your way into Echoes, an exciting action puzzle game in which players collect crystals within many surreal, artistic worlds. The player controls Charlie, a girl who was transported to another realm while dreaming in art class.Collect crystals and avoid Echoes, the translucent and deadly ghost versions of yourself. Fight back with power ups across multiple worlds and game modes!' FROM games WHERE igdb_id = 91392 ON CONFLICT (game_id, language_code) DO NOTHING;
