INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hobo: Prison Brawl', 'Continues the story of the hobo. This time you are awoken by your prison cellmate, who is upset at the state of your shared toilet. You don''t take kindly to this, and a brawl breaks out where you take on any and all comers. Cartoon graphics and disgusting unlockable combos await. Many combos from the first game you have unlocked from the beginning.' FROM games WHERE igdb_id = 294146 ON CONFLICT (game_id, language_code) DO NOTHING;
