INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cargo-bridge', 233767, '2009-05-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6yl8.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cargo Bridge', 'The most popular game Cargo Bridge from Limex Games becomes available to millions of our fans on the iPad in 2011. In Cargo Bridge your goal is to build bridges within each one of 24 levels, that allows your little workers to move heavy cargo (which include crates, safes, and even elephants) from one side of a valley to the other. With every level, the difficulty increases. You have to build bridges across larger gaps, up and down inclines, and around obstacles in your path. You are also given access to new building materials. If you want to have a break from game levels, just enter the Challenge mode. Use money collected in game levels to build the longest bridge you can.' FROM games WHERE igdb_id = 233767 ON CONFLICT (game_id, language_code) DO NOTHING;
