INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Staunch Defense', 'Staunch Defense is a tower defense game with plenty of depth and strategy. Featuring 20 different towers, 6 buildings such as cottages and walls and a large number of technologies there are many ways you can approach each map. Each of the 24 maps has its own selection from the large variety of different enemies and thus requires its own strategy.' FROM games WHERE igdb_id = 175186 ON CONFLICT (game_id, language_code) DO NOTHING;
