INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('blood-bowl', 5649, '2009-06-26', 45, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2a7t.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc82hv.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blood Bowl', 'Blood Bowl is a combination of a tactical and sports game. The basics are extremely simple: two teams, one ball. The team that carries the ball into the opponent''s end zone scores a touchdown, the team with the most touchdowns at the end of the game is the winner. However, it’s how you decide to do this that makes things interesting, the ends justify the means! It’s not just the players you have at your disposal either. You can bribe the referee to look the other way as you cripple or trample annoying opponents and hire illegal wizards to give you a hand directly from the crowd… Blood Bowl severely tests the finest tacticians'' strategies. There are many races to accommodate every player’s profile (23 in the Chaos Edition, 20 in the Legendary Edition, 9 in the Standard Edition) and even more strategies for experimenting. Winning a game requires a strong game-sense and a lot of self-control. For the player''s enjoyment, omnipresent humour and the use of spells, weapons, and other non-regulatory actions place Blood Bowl outside of the classic sport simulation genre.' FROM games WHERE igdb_id = 5649 ON CONFLICT (game_id, language_code) DO NOTHING;
