INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kernel Panic', 'Kernel Panic is a game about computers. Systems, Hackers and Networks wage war in a matrix of DOOM! The only constraints are time and space; unlike other real time strategy games, no resource economy exists in KP.  All units are free in this game, every factory built will be spamming units at all times. You can build more factories, but only on pre-defined areas (geothermal vents). All that remains is pure strategy and tactics.  KP makes for a frantically fast-paced, action-oriented game, with a very unique graphical style.' FROM games WHERE igdb_id = 110886 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 110886 AND ge.slug = 'real-time-strategy-rts' ON CONFLICT DO NOTHING;
