INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Oregon Trail', 'The Oregon Trail is a strategy video game developed by Gameloft New York and Gameloft Shanghai and published by Gameloft. It was released for Java ME-based mobile phones in 2009; a high-definition version was later released for iOS the same year. The game was then ported to DSiware, followed by a number of other mobile operating systems and devices. The game was followed by two sequels: The Oregon Trail: Gold Rush and The Oregon Trail: American Settler.' FROM games WHERE igdb_id = 78864 ON CONFLICT (game_id, language_code) DO NOTHING;
