INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Free Realms', 'Free Realms was a massively multiplayer online role playing video game, developed by Sony Online Entertainment (SOE) for the PC, Mac, and PlayStation 3, set in a fantasy-themed world named Sacred Grove. The game was released on April 29, 2009, for the Windows PC. The game restricted free to play up to level 20, although there was access to additional game content via a membership fee. The game allowed the player to fight, interact with other players, and more. It was closed on March 31, 2014; SOE stated that they no longer had enough resources to maintain so many servers.' FROM games WHERE igdb_id = 20279 ON CONFLICT (game_id, language_code) DO NOTHING;
