INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SingStar: Mallorca Party', 'SingStar: Mallorca Party is a karaoke game exclusively released in Germany. I features 30 German songs which are meant to be consumed along with a lot of alcohol. There are no changes to the gameplay formula: player(s) sing into a microphone and the game gives points based on the performance. The only basis of assessment is if the correct note is hit with the correct timeing; the sung words or octave does not play into the result.' FROM games WHERE igdb_id = 44700 ON CONFLICT (game_id, language_code) DO NOTHING;
