INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scally''s World: Numbers & Sums', 'Another educational title developed by Topologika Software in the ever so obscure Scally series stating:  Introduces children to numbers and counting with 17 carefully graded activities  National Numeracy Strategy-based software  Designed for 3-7 year olds  Foundation & Key Stages 1, Scotland to P3  Clearly spoken number names help children recite numbers along with the program  Stunning graphics and real speech motivate children  Also suitable for special educational needs' FROM games WHERE igdb_id = 110566 ON CONFLICT (game_id, language_code) DO NOTHING;
