INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chicken Blaster', 'Things have gone completely haywire for our humble poultry-farming friend! Crazy chickens have infiltrated his once anonymous and boring life -- and now all of his chickens are going mad! Chickens on rockets! Chickens on water skis! Chickens jumping on trampolines! In Chicken Blaster, it''s time to put those crazy chickens in their place. Blast them off the farm with an arsenal of weapons -- but keep an eye on those egg-wielding birds determined to defend their new insane way of life.' FROM games WHERE igdb_id = 50682 ON CONFLICT (game_id, language_code) DO NOTHING;
