INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shooting Love, 200X', 'The historic success story of the arcades! Introducing the "Shmups Skill Test", a way to evalute your skills as a "gamer age". The high brow style of "EXZEAL", with 4 types of craft to choose from. The classic style of "TRIZEAL Remix", where you can switch between wide shots, lasers and missiles to strategically conquer a wide variety of stages. And, the console-only abstract shooter, "MINUS ZERO". Enjoy these 4 diverse shooters all from one package!' FROM games WHERE igdb_id = 7187 ON CONFLICT (game_id, language_code) DO NOTHING;
