INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Supercar Challenge', 'SuperCar Challenge for the PlayStation 3 is a high-octane racing game featuring both arcade and simulation tarmac thrills.  Building on the critically acclaimed Ferrari Challenge racing simulation engine, SuperCar Challenge heralds the addition of the sexiest supercars on the planet while improving on its spiritual prequel in every way. Over 40 cars are available to throw around the most celebrated corners on the racing calendar. Experience the thrills and spills that come with harnessing the full grunt of an Aston Martin DB9, the Ferrari FXX, the McLaren F1 and many more! More than 20 tracks will also be available, with old favourites such as Silverstone and Spa mixed in with the joys of Nürburgring and the fictitious charms of Riviera.' FROM games WHERE igdb_id = 7462 ON CONFLICT (game_id, language_code) DO NOTHING;
