INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trivial Pursuit', 'This is the 2009 video game incarnation of Horn Abbot International Ltd''s classic board game, Trivial Pursuit. The game involves answering questions on one of six subject categories to gain moves, and answering questions on special squares to gain one of the six ''Wedges'' you need to gain the right to take on the final winning question. Questions are aimed at British players - many entertainment questions are based on British TV, and sport questions relate to popular British sports.' FROM games WHERE igdb_id = 12970 ON CONFLICT (game_id, language_code) DO NOTHING;
