INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fasmo 2: Fasmo Goes West', 'In this game, you take control of Fasmo, the sentient stick bug from outer space. He''s accidentally teleported himself into the wild west, and must contend with ferocious bandits, and scheming policemen. Features two controversial mini-games, and an original score.' FROM games WHERE igdb_id = 169513 ON CONFLICT (game_id, language_code) DO NOTHING;
