INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'F-16 Multirole Fighter', 'With innovative technologies such as fly-by-wire controls, sophisticated systems for night and all-weather operations and the ability to carry a variety of weapons, the F-16 continually proves to be the workhorse of the USAF. Victorious in all of its air-to-air engagements, the awesome reputation of the F-16 is undisputed.' FROM games WHERE igdb_id = 16011 ON CONFLICT (game_id, language_code) DO NOTHING;
