INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Luminous Arc 3', 'Luminous Arc 3 (ルミナスアーク3 アイズ Ruminasu Āku Tsū Aizu?, Luminous Arc 3: Eyes) is a role-playing video game developed by imageepoch and published by Marvelous Entertainment. In Luminous Arc 3, witches have ceased to exist, but their legacy lives on through "Magi". There are two people who are associated with witches. One is Sarah, who wants to become the legendary witch and the Holy Witch Sylvia.' FROM games WHERE igdb_id = 25100 ON CONFLICT (game_id, language_code) DO NOTHING;
