INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Neighborhood Games', 'Welcome to the Neighborhood where the fun never ends. Play 24 unique twists on classic neighborhood games including Football, Golf, Tennis, Ladder Golf, Lawn Darts, Horseshoes, Bocce, and more. Enjoy intuitive controls for a pick up and play experience for the whole family-use the Wii Remote to throw the football, shoot the basketball, toss the horseshoe and roll the bocce ball just to name a few!' FROM games WHERE igdb_id = 5066 ON CONFLICT (game_id, language_code) DO NOTHING;
