INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'No Gravity: The Plague Of Mind', 'In a distant future, a mysterious mind disease is spreading and the road to the cure lies somewhere in the depths of space. Choose between the best pilots and complete a wide range of missions in this fast paced 3D space shooter. Save humanity by a number of means such as: destroying enemy ships or their bases, escorting allied ships, retrieving cargos, defending convoys from pirates, raiding ground bases, clearing mine fields and infiltrating planets...' FROM games WHERE igdb_id = 42846 ON CONFLICT (game_id, language_code) DO NOTHING;
