INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kurai Nichiyoubi: Sombre Dimanche', 'It''s the sixth day of incessant rain in the city. The entire country had been shaken by a series of bizarre murders, occuring late at night on a deserted street. Because slashing throats and tearing open stomachs were his modus operandi, the criminal was rumored to be a "Modern-day Jack the Ripper."' FROM games WHERE igdb_id = 260982 ON CONFLICT (game_id, language_code) DO NOTHING;
