INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('squeeballs-party', 21213, '2009-11-12', 55, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6ejq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scs5ii.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Squeeballs Party', 'Squeeballs are small creatures manufactured on a secret island somewhere in the Pacific Ocean. Before they can be sold to children as toys around the world, Squeeballs must be fully tested…to the point of destruction. That''s where the player comes in. They blow up, slice, smack, punch, bowl, shoot and skim the Squeeballs through 11 main game challenges.' FROM games WHERE igdb_id = 21213 ON CONFLICT (game_id, language_code) DO NOTHING;
