INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('free-friends', 127665, '2009-04-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1v9o.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7i32.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Free Friends', 'Yui Kurahashi was an innocent young girl born and raised in a rich family that didn’t treat her well. After getting into a fight with her parents, Yui wanders the town at night. A friend suggest she join a message board called Free Friends. With nowhere left to go after running from home, she turns to the site called “Free Friends” looking for help–unknowing that it was a site for hook-ups. The one who offers his hand to her is a teacher at her school. When her teacher meets her and forces himself upon her, their relationship of depravity begins. In Free Friends you play the role of Yui’s teacher, and the choices you make determine how dark a road the two of you travel. Will you walk the path of darkness and continue coercing her through blackmail and other means? Or will you try to play the savior Yui hoped for? A variety of corrupt and twisted endings await exploration… along with one of hope.' FROM games WHERE igdb_id = 127665 ON CONFLICT (game_id, language_code) DO NOTHING;
