INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tony Hawk''s Vert', 'Drop into half-pipe skateboarding insanity in the newest mobile installment to the award-winning franchise featuring the world’s greatest skating legend. With an innovative point-of-view, perform incredible tricks like Tony''s 900 and get fans screaming to score awesome point combos! This fast paced skating game will have you performing complex aerial tricks in no time with its easy control system. To mix it up, play bonus mini-games such as star reporter and capture the best tricks on your in game camera. The better the trick the better picture. To get to the top, you have to get vertical!' FROM games WHERE igdb_id = 199792 ON CONFLICT (game_id, language_code) DO NOTHING;
