INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Schrödinger''s Rat', 'Set in the laboratory of world-renowned rat-scientist Paradox, Schrodinger''s Rat combines an experiment in quantum physics with labyrinth-like maze challenges. Working through all the elements of the periodic table, Paradox must discover the ideal path for rescuing all of the rats that have given their lives to science throughout time.' FROM games WHERE igdb_id = 21776 ON CONFLICT (game_id, language_code) DO NOTHING;
