INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Iron Sight', 'Iron Sight is a turn-based strategy game, based in a post-apocalyptic world. The player has the option of picking between two different factions, the Corporation or Rebellion. The Corporation is essentially the governmental control agency or military/ oppressor and the Rebellion is just that; a group of rebels/freedom fighters battling "the man". During different missions, enemies need to be taken out using a mech-like vehicle.' FROM games WHERE igdb_id = 98003 ON CONFLICT (game_id, language_code) DO NOTHING;
