INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Water Sports', 'Water Sports gives players the opportunity to go Kite Surfing, Wake Boarding, Wind Surfing and Jet Skiing all without having to get wet or leave your living room! Challenge yourself on the Wii Balance Board, race against your friend in multiplayer mode, or work together in cooperative Wake Boarding. Water Sports is designed to be an easy to learn but difficult to master game for the family that feels more like an arcade game than a simulation.' FROM games WHERE igdb_id = 5262 ON CONFLICT (game_id, language_code) DO NOTHING;
