INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NHL 2K10', 'NHL 2K10 is an ice hockey simulation developed by Visual Concepts and published by 2K Sports, part of the NHL 2K series. It was released on September 15, 2009 for Wii, Xbox 360, PlayStation 3, and PlayStation 2. Randy Hahn and Drew Remenda provide commentary as they did for NHL 2K9. As of 2011, NHL 2K10 was the final 2K Sports ice hockey video game released for the PlayStation 3, PlayStation 2 and Xbox 360, as NHL 2K11 was released only for the iPhone & Wii.' FROM games WHERE igdb_id = 5069 ON CONFLICT (game_id, language_code) DO NOTHING;
