INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Galaxy Trek', 'Also check out Galaxy Trek for iPad - now available in the App Store. The galaxy is being overrun by an invading horde of enemies know as Swarmers. The swarmers are fast and ferocious and attacks in swarms, hence their name. The swarmers have decimated the entire fleet of warships leaving the inhabited planets and remaining spaces stations defenseless.' FROM games WHERE igdb_id = 197717 ON CONFLICT (game_id, language_code) DO NOTHING;
