INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Queen''s Blade: Spiral Chaos', 'With the Queen''s Blade Tournament ongoing, rumors arise about a dark, mysterious power threatening to destroy all of Gainos. With the new heroes, Cute and Jean, and the rest of the Queen''s Blade competitors, they seek to find the root of this power and destroy it to restore balance to the land.' FROM games WHERE igdb_id = 38458 ON CONFLICT (game_id, language_code) DO NOTHING;
