INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Delaware St. John: Volume 2 - The Town with No Name', 'Deep in the woods of northern Maine there lies a town, a town that has never been recorded on any map. For twenty years the town has stood vacant after all occupants vanished one fateful night. The voices have called to Delaware and as he explores the Town with No Name he comes to realize that the most important secret he''s about to uncover is his own. Explore a mysterious city in Delaware St. John – The Town with No Name.' FROM games WHERE igdb_id = 71043 ON CONFLICT (game_id, language_code) DO NOTHING;
