INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ju-on-the-grudge', 4945, '2009-07-30', 42, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2xfc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/xujgdraghfese2ydn0se.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ju-on: The Grudge', 'It is said that when a person dies with a deep and burning grudge, a curse is born. When an average housewife in Nerima, Japan, was murdered in a grisly fashion, it gave rise to a curse so powerful that it threatens to kill at a pace thought unimaginable before. The curse manifests on those who encounter the curse by any means, such as entering the house or being in contact with somebody who was already cursed. Once Erika Yamada is exposed to the curse while searching for her dog in an abandoned warehouse, the entire Yamada family is put in grave danger as soon as she reunites with them at home. They must now face their individual challenges alone, and only by overcoming the curse together will their family truly be free again. JU-ON: The Grudge is billed as the first “Haunted House Simulator” where accessibility and instant scares are given priority over story and game play depth. Using the Wii Remote as a flashlight, players move forward with the touch of a button and explore haunted areas such as an abandoned warehouse, a dimly-lit hospital, and a mannequin factory. Much like a haunted house, the player must proceed forward even after being frightened.' FROM games WHERE igdb_id = 4945 ON CONFLICT (game_id, language_code) DO NOTHING;
