INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Clever Kids: Creepy Crawlies', '"Hi, I''m Sprocket.... Join me on a journey to meet some of the slimiest, squirmiest, wriggliest creatures on earth. From the tiniest insects to huge bettles, giant centipedes and deadly spiders, you''ll learn everything you need to become a master of creepy-crawly knowledge!" - Play a host of Fun games: help a dung beetle, defend a garden against centipedes and spiders, solve jigsaws, beat the Quiz and much more! - Clever Kids games make learning and development Fun For all ages.' FROM games WHERE igdb_id = 268113 ON CONFLICT (game_id, language_code) DO NOTHING;
