INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Stable: The Spring Rider', 'Star stable: The Spring Rider takes place in the Jorvik Bay during spring and its main equestrian orientation is dressage. During the quests you are learning more of dressage and improve your horse riding. You also help different characters. You’re preparing yourself for prestige dressage competition in Rodilla Riding School and to be chosen as riding instructor for the spring horse camp.' FROM games WHERE igdb_id = 283568 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 283568 AND c.slug = 'pixel-tales' ON CONFLICT DO NOTHING;
