INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dreamscaper', 'Dreamscaper is an English Yume Nikki fangame. The game stars Natalie, a young girl who locked herself in her room. According to the developer, Dreamscaper uses American culture to contrast against the large amount of eastern/Japanese fangames out at the time. Dreamscaper plays like most fangames, focused on collecting effects and exploring Natalie''s dream world.' FROM games WHERE igdb_id = 201196 ON CONFLICT (game_id, language_code) DO NOTHING;
