INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Onore no Shinzuru Michi wo Yuke', 'An action puzzle game based on karakuri, ukiyo-e art, and The Fifty-Three Stations of the Tokaido. Controlling a series of ninjas, players must work to advance through a series of floors against a time limit, working together with the replays of their past attempts in order to succeed.' FROM games WHERE igdb_id = 69196 ON CONFLICT (game_id, language_code) DO NOTHING;
