INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('armies-of-gielinor', 130621, '2009-01-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7n5c.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scq5cs.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Armies of Gielinor', 'Armies of Gielinor is a turn based strategy game involving the interaction of units on a square grid. Many units that the player controls were aligned with a particular god, and require the player to have a suitably high favor to summon them. Favour was increased by summoning a unit of the highest level possible for that god. The aim of the game was to fulfill one of three victory conditions, before any of the other players. These victory conditions were: 1. Defeat all opponents. 2. Accumulate the maximum victory points for the level. 3. Accumulate the most victory points when the turn limit expires.' FROM games WHERE igdb_id = 130621 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 130621 AND ge.slug = 'turn-based-strategy-tbs' ON CONFLICT DO NOTHING;
