INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Garfield Gets Real', 'In Garfield Gets Real, players switch between Garfield and Odie as they play through seven areas of the game that all connect from the cartoon universe to the real world. Each area has a key story challenge that progresses the player through the game''s chapters while completing 150 smaller tasks that will help them reach the key story challenges.' FROM games WHERE igdb_id = 4882 ON CONFLICT (game_id, language_code) DO NOTHING;
