INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('petka-9-proletarskiy-glamur', 52763, '2009-01-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/ba7srocpunuucrz9j5cv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/orzlwsmgsul830ddjpxl.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Petka 9: Proletarskiy Glamur', 'The ninth installment in the long-running Russian adventure game series, sub-titled Proletarskiy Glamur ("Proletarian Glamour"), once again follows the adventures of the titular Petka, his commander Chapaev, and the sexy Anka - all real participants of the Russian Civil War of 1918, who became the target of countless jokes during the Soviet period. This time, the trio receives an assignment to travel to the year 2150! It appears that in 2008, the USA and other countries decided to use Russia as a dumping ground for garbage. Fearing that the Russian would object such treatment of their country, the Americans used an advance technique to brainwash them, rendering them helpless. Such as the situation when the heroes arrive in New Moscow of the 22nd century, determined to save their homeland... Proletarian Glamour is a puzzle-solving adventure game. The player advances the story by talking to characters, and completing various tasks, mainly involving manipulation of inventory items. Just like the previous installment, the game is done in full 3D, both for characters and background graphics.' FROM games WHERE igdb_id = 52763 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 52763 AND ge.slug = 'adventure' ON CONFLICT DO NOTHING;
