INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dodge Racing: Charger vs Challenger', 'Rev your engines and hit the highways and byways of the USA in the ultimate racing tournament. Dodge Racing: Charger vs. Challenger pits two of the mostic American vehicles in a Battle Royale to determine which one is the greatest muscle car of all time. Burn rubber and peel out in your Dodge Charger or Dodge Challenger, pushing these bad boys to the limits to win Championship Points for your team' FROM games WHERE igdb_id = 50965 ON CONFLICT (game_id, language_code) DO NOTHING;
