INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Diamon Jones: Amulet of the World', 'Explore the ancient world of Egypt in this mystical Adventure game! Help Diamon Jones become the rich and famous hero he wants to be, as you explore the Pharaohs` temples and find amazing treasures. Travel all over the world on your incredible journey to first find the Amulet of the World, and then replace it, when the natural order of the world has been upended. Can you help Diamon Jones save the world?' FROM games WHERE igdb_id = 59921 ON CONFLICT (game_id, language_code) DO NOTHING;
