INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('time-of-shadows', 90468, '2009-09-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob6qo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/qw4aaaqdlhftgipxjrlb.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Time of Shadows', 'Sequel to the well known Action-RPG Blood Magic The immortal Modo has been prostrated. Trying to destroy the Earth he died and didn''t accomplish his monstrous plans. But evil won''t leave the world without a desperate struggle. The absolute is ruined, fragile balance of the forces that remained for 10 years has fallen to pieces. The world remained unprotected and legions of shadows lashed it and drowned it in sorrow, horror and suffering. There is practically no more time left. The Hero has to start a risky journey in the labyrinths of other worlds to stop the invasion of non-natural creatures. Key features Balanced magic system including 12 schools of magic and over 100 spells that can be combined A dynamic combat system using combos, skills and magic. Dozens of elaborated characters and monsters Advanced NPC system Dangerous adventures and fascinating quests in the unexplored world of shadows Atmospheric sounds and music themes' FROM games WHERE igdb_id = 90468 ON CONFLICT (game_id, language_code) DO NOTHING;
