INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('phantasy-star-portable', 21873, '2009-04-03', 67, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3zah.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scpvgi.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Phantasy Star Portable', 'Sega''s long-running RPG goes handheld for the first time in North America with Phantasy Star Portable, a story set between the events of Phantasy Star Universe and Ambition of the Illuminus. Players return to the Gurhal system where they join the new character Vivienne in an attempt to investigate and clear out an area contaminated after the perceived eradication of the alien SEED menace. Gamers can choose from a wide variety of options when creating a custom avatar, and then set about meeting new characters and collecting more than 150 items. Multiplayer fans can also join up to three friends for wireless co-operative exploration and combat.' FROM games WHERE igdb_id = 21873 ON CONFLICT (game_id, language_code) DO NOTHING;
