INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Towelket: One More Time 6 - Devils&Devils&Nightmares&Devils', 'Towelket: One More Time 6 Devils&Devils&Nightmares&Devils is a story-heavy adventure game made in RPG Maker 2000. The game is virtually identical to a previous Towelket release known as Towelket Reverse (Ura); the main differences between those two games are a handful of bugfixes and a different ending scene.' FROM games WHERE igdb_id = 147157 ON CONFLICT (game_id, language_code) DO NOTHING;
