INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chaotic: Shadow Warriors', 'Prepare to prove your mettle in the battle arena. In Chaotic: Shadow Warriors, the intense fighting action of the TV series combines with the gripping strategy of the card game to provide a uniquely exciting turn-based arena combat experience. Assume the role of a Chaotic creature and get ready to dominate your opponents in animated bouts bursting with explosive action.' FROM games WHERE igdb_id = 24339 ON CONFLICT (game_id, language_code) DO NOTHING;
