INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wakfu: Les Gardiens', 'Wakfu: Les Gardiens is a browser game intended as an initiation to MMORPGs for young teens and a crossover link to the animated series "WAKFU", released by ANKAMA and broadcasted by France 3. Since 2014, ASHES, an association composed by three players (Krayth, Kyosset and Starlight) worked on its restoration. Reconstituted to be identical to the original, the game is online on a free fan-made server without any kind of monetization.' FROM games WHERE igdb_id = 167643 ON CONFLICT (game_id, language_code) DO NOTHING;
