INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '0 Day Attack on Earth', 'Earth is under attack by massive creatures from outer space. With a huge arsenal of heavy-power artillery at your disposal, climb into your fighter jet and wage fierce battles against these gruesome aggressors. 0 Day Attack on Earth gives you full range of motion and attack while you engage in air strikes over real-world cities, such as Tokyo, New York and Paris. Team up with, or battle against players from around the world in online co-op. Only you can save Earth from complete annihilation.' FROM games WHERE igdb_id = 6172 ON CONFLICT (game_id, language_code) DO NOTHING;
