INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Styrlitz 4: The Matrix - A Step to Death', 'Styrlitz 4 is a comedic point-and-click adventure game. It is a parody of the popular Soviet television series Seventeen Moments of Spring about the exploits of a Soviet spy operating in Nazi Germany under the name Max Otto von Stierlitz. This is the fourth game in the series. In this entry in the series, Styrlitz, now retired, receives a message from a white rabbit that informs him that not all nazis were defeated. The game mainly parodies The Matrix, but there are also references to other movies and TV shows of the 2000s.' FROM games WHERE igdb_id = 281658 ON CONFLICT (game_id, language_code) DO NOTHING;
