INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lit', 'Venture into the dark hallways of a haunted high school and help guide emo teenager Jake as he searches for his lost girlfriend Rachael. Solve light-themed puzzles using a variety of gameplay mechanics including slingshots, light bulbs, windows, matches, lamps, and TV sets. Think your way around deadly creatures from the darkness in an effort to reach each room''s exit door without being swallowed up by the shadows. Are you brave enough to puzzle through the darkness...?' FROM games WHERE igdb_id = 21264 ON CONFLICT (game_id, language_code) DO NOTHING;
