INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Age of Conquest: Asia', 'Age of Conquest ASIA is a medieval risk-like turn-based strategy game where you take the reins of a budding empire and struggle against fellow empires for control of Asia. In one game, up to 20 players vie for supremacy, but only one can be victorious. Every game you win pushes up your score, until you don''t just dominate the world, but also your fellow players. Then all will be in your shadow and not just peasants, but even kings will worship you! All this can be yours, but only if you triumph.' FROM games WHERE igdb_id = 174583 ON CONFLICT (game_id, language_code) DO NOTHING;
