INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Half-Minute Hero', 'You have 00:30 seconds to save the world! Prepare for the fastest, most frantic gameplay ever! Conquer over 100 levels totaling more than 20 hours of gameplay, 30 seconds at a time! Challenge the missions on your own or connect wirelessly for blazing-fast, head-to-head competition!' FROM games WHERE igdb_id = 21943 ON CONFLICT (game_id, language_code) DO NOTHING;
