INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Starry Sky: in Summer', 'The second of the four Starry Sky games starring the characters from the drama CD''s of the same name. Starry Sky takes place at Seigatsu Gakuen, a school which specializes in horoscopes, astronomy and other related topics. The main characters are all based on horoscopes. Starry Sky Summer features Homare Kanakubo (Taurus), Ryuunosuke Miyaji (Scorpio) and Azusa Kinose (Sagittarius).' FROM games WHERE igdb_id = 202820 ON CONFLICT (game_id, language_code) DO NOTHING;
