INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deca Sports 2', 'With its easy-to pick up and play controls, Deca Sports 2 will make everyone in your family experts in a wide range of new sports. Check, dodge and smash the competition across all of the included events: Ice Hockey, Dodge Ball, Tennis, Darts, Speed Skating, Mogul Skiing, Petanque, Kendo, Motorcycle Road Racing and even Synchronized Swimming! The spirit of competition is more fun than ever!' FROM games WHERE igdb_id = 20695 ON CONFLICT (game_id, language_code) DO NOTHING;
