INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spice and Wolf: The Wind that Spans the Sea', 'Part business simulator, part dating game, get ready to step into the shoes of Kraft Lawrence as you strive to take Holo back to her hometown of Yoitsu. Having secured a contract to collect some money from a town on the other shore, everything should be plain sailing ahead for the duo, but of course, the best laid plans of mice and wolves often go awry…' FROM games WHERE igdb_id = 123448 ON CONFLICT (game_id, language_code) DO NOTHING;
