INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Hero: Firefighter', 'As a courageous fireman in My Hero: Firefighter, players must react quickly, drive fast, and extinguish life-threatening flames using real firefighting equipment in dangerous house fires, forest fires, and chemical explosions. Earn awards and medals for your acts of bravery on your way up to becoming Captain of the fire department and a true national hero.' FROM games WHERE igdb_id = 47862 ON CONFLICT (game_id, language_code) DO NOTHING;
