INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hot Potato Online', 'Blast your opposition with a potato bomb while avoiding incinerating yourself in this original arcade sport! Enter the arena with three local or online friends and AIs in teams or free-for-all. Customize the match options and create your own arenas using the map editor.' FROM games WHERE igdb_id = 288009 ON CONFLICT (game_id, language_code) DO NOTHING;
