INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arkanoid Live!', 'First appearing in the 1980’s as a new style block-breaking game, ARKANOID, appears on Xbox LIVE Arcade having accomplished even further evolution. Enjoy Arkanoid in high-definition with beautifully choreographed background movies and background music. Loaded with 120 stages in all and colorful cooperative and versus modes.' FROM games WHERE igdb_id = 72559 ON CONFLICT (game_id, language_code) DO NOTHING;
