INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Unbound Saga', 'Get a taste of the smashtastic adventure of Unbound Saga, a 3D side-scrolling brawler set in a satirical comic book universe, where enemies are drawn onto the screen and madcap battles travel from panel to panel through a twisted, post-apocalyptic landscape! Realtime physics and destructible objects turn anything into a weapon, so grab the controller and RAGE OFF THE PAGE!' FROM games WHERE igdb_id = 21101 ON CONFLICT (game_id, language_code) DO NOTHING;
