INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pinball Heroes', 'Classic arcade pinball action in the palm of your hands. With multiple Pinball Heroes pinball tables to download - each one based off of a different hit PlayStation franchise - you''ll always have a new challenge to conquer. So whether you’re a casual gamer or a true pinball wizard, Pinball Heroes for the PSP gives you authentic arcade pinball experience - anytime and anywhere.' FROM games WHERE igdb_id = 42817 ON CONFLICT (game_id, language_code) DO NOTHING;
