INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sono Hanabira ni Kuchizuke o: Amakute Hoshikute Torokeru Chuu', 'Sono Hanabira ni Kuchizuke o: Amakute Hoshikute Torokeru Chuu is an adult visual novel and the seventh game in the Sono Hanabira ni Kuchizuke o series of games. It introduces a new couple: Suminoe Takako, a young and still inexpert teacher at the elementary department of St. Michael''s School for Girls, and one of her students, the daring ojousama Horaisen Runa.' FROM games WHERE igdb_id = 12218 ON CONFLICT (game_id, language_code) DO NOTHING;
