INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MonsterKill', 'They''re cute, they''re cheeky - you just want to slice the life out of the little monsters! Hordes of tiny terrors have broken free of their chains and are running amok! Summon a variety of spells as you battle against these classic mini-monsters in multiple game modes: Normal, Endless & Onslaught!' FROM games WHERE igdb_id = 197807 ON CONFLICT (game_id, language_code) DO NOTHING;
