INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mahjong Mysteries of the Past', 'A meteor is all near Planet Earth, bringing total collapse and death. Only the Ancient Locket can prevent the catastrophe. Long ago it was divided into 10 parts and scattered about in different parts of the world. Set up for past with an experienced traveler Andy Brown to put parts of the relic together and postpone the doomsday. Famous Mahjong will entertain you and help to gain patience and universal knowledge.' FROM games WHERE igdb_id = 25289 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 25289 AND ge.slug = 'puzzle' ON CONFLICT DO NOTHING;
