INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Exit Fate', 'Exit Fate is a freeware RPG inspired by Suikoden and Chrono Cross. The story centers on Daniel Vinyard, a colonel within the Kirgard Army as the kingdom prepares for war against it''s neighbour, the State Union of Zelmony. Caught in a whirlwind of political intrigue, recruit seventy-five potential party members as you explore a continent at war.' FROM games WHERE igdb_id = 124555 ON CONFLICT (game_id, language_code) DO NOTHING;
