INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cosmic Break', 'Cosmic Break (Japanese: コズミックブレイク, Hepburn: Kozumikku Bureiku, also stylized as CosmicBreak) is a free to play 3D MMO third-person shooter with big robots and colorful, explosive battles in an anime style. The game was developed and published by the Japanese company CyberStep, Inc. and was officially released in several countries. As is the case with GetAmped2, Cosmic Break also has various NPCs and playable characters voiced by famous Japanese voice-over artists.' FROM games WHERE igdb_id = 80556 ON CONFLICT (game_id, language_code) DO NOTHING;
