INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'M&M''s Beach Party', 'Your favorite M&M''S candy characters are serving up summertime fun in M&M''S Beach Party! Get on your feet and compete in six unique and physically challenging games like the Kayak Race, the Mr. Runch Slam, and Skee-Ball! What day at the beach would be complete without Beach Volleyball? Bump, set, and spike your way to victory during a full-length volleyball game!' FROM games WHERE igdb_id = 50703 ON CONFLICT (game_id, language_code) DO NOTHING;
