INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Global Pokédex Plus', 'Welcome to GPXPlus, the best place to hatch ''em all! Collect and hatch eggs from every Pokémon game, along with several unique ''Novelty'' Pokémon. Raise and evolve your Pokémon from their basic forms to their final stages, filling your Pokédex as you go. Embark on artwork-and-story-rich Explorations to hunt for Legendary Pokémon and rare items. Engage in realtime Pokémon battles with other users and AI-controlled NPCs... and much, much more!' FROM games WHERE igdb_id = 151645 ON CONFLICT (game_id, language_code) DO NOTHING;
