INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Family Fun Football', 'In this arcade-style casual sports game for everyone to enjoy, play against friends and family in vibrant themed football stadiums, or perhaps even in space! Choose to be one of the game''s quirky characters, featuring animals, aliens and robots, or unlock the mode to play as your own Mii. The ability to coach teams with a simple offensive and defensive playbook coupled with intuitive Wii Remote controls makes the game appealing to all ages for a fun pick-up and play party experience.' FROM games WHERE igdb_id = 50651 ON CONFLICT (game_id, language_code) DO NOTHING;
