INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pig Rush', 'Pig Rush is a hilarious and addictive platform game where you help Jumpy the pig run away from the farm. On the way, you encounter deep ravines, fire, and moving platforms. Grab a fire hat to protect you from fire, and get a power up to turn into an invincible giant pig!! Pig Rush is a game that is fun for the whole family. Kids love it - if they can get it away from their parents!!' FROM games WHERE igdb_id = 88107 ON CONFLICT (game_id, language_code) DO NOTHING;
