INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Camp', 'In Space Camp you begin as an aspiring astronaut in training. After rocketing yourself to the moon, you must engage in a series of futuristic, furiously fun missions in order to return home to Earth. With the help of your own robot, you will perform activities like scientific experimentation, controlling spacecraft and even defending the moon from invaders.' FROM games WHERE igdb_id = 208867 ON CONFLICT (game_id, language_code) DO NOTHING;
