INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monster Mash', 'In a distant fairy-tale world, the villagers of Curly Valley are being attacked by legions of quirky and bizarre monsters.  Fortify villages with various towers, upgrades and unusual defensive armaments to repel these mysterious invaders and protect the grateful villagers who cheer your every conquest!  Get ready for the coming onslaught in this addictive, strategic adventure.' FROM games WHERE igdb_id = 16058 ON CONFLICT (game_id, language_code) DO NOTHING;
