INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Coraline', 'Coraline lets players take on the role of the adventurous heroine Coraline and interact with the wondrous characters from the movie while navigating the scheming Other Mother''s web of deceit in a fantastical adventure through two distinct and interactive worlds. Players engage in unique mini-games and adventures with Coraline''s friends Wybie and Cat as they collect items that will unlock the mysteries of the Other World.' FROM games WHERE igdb_id = 4771 ON CONFLICT (game_id, language_code) DO NOTHING;
