INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rainbow Islands: Towering Adventure!', 'Rainbow Islands: Towering Adventure! is a part of the Bubble Bobble series. And thus this game features slightly similar gameplay. You play as Bubby or Bobby (or both, with a friend) and have to make your way to the top of multiple long, vertical stages with the aid of rainbows, which you can create.' FROM games WHERE igdb_id = 21241 ON CONFLICT (game_id, language_code) DO NOTHING;
