INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('legend-hand-of-god--1', 15793, '2009-04-02', 40, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1s50.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/st1dcaxrsxw89fab159r.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Legend: Hand of God', 'Become immersed in the fantastic world of Aris is a world populated by Orcs, Elves, Dwarfs and Humans. Complete more than 30 challenging quests to find the three parts of the Hand of God amulet and save Aris from impending doom. But beware of the more than 30 types of monsters and big bosses that are awaiting you as you fight your way through huge randomly-generated dungeons and detailed, individually designed landscapes. But your hero will not be all alone. He will be accompanied by Luna, a light elf is serving as companion, campaign guide and mouse cursor at the same time. With Legend: Hand of God, the German team Master Creating has created an epic Action RPG that raises the bar for the genre, thanks to the involvement of well known industry veterans such as Paul Campion and Andreas Adamek. Explore a gigantic, continuous world where you can seamlessly journey from the highest mountain to the deepest dungeon without a single loading screen. Cinematic combat system with combat in movie choreography quality, but still as easy to control as in standard Action RPGs. Dynamic environment system, e.g. fog, rain, snowstorms. Character creation that allows appearance and abilities shifting, the latter by combining 2 out of 5 available skill trees. Strong storyline that will grab and hold you all the way till the end. A light elf that serves as companion, mouse cursor, light source and campaign guide at the same time.' FROM games WHERE igdb_id = 15793 ON CONFLICT (game_id, language_code) DO NOTHING;
