INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hidden-expedition-devils-triangle', 64723, '2009-10-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8oeo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sctmkh.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hidden Expedition: Devil''s Triangle', 'Hidden Expedition: Devil''s Triangle is the fourth entry in the hidden object game series produced by Big Fish Games since 2006. As in most recent titles of the genre, the adventure elements are more pronounced with full inventory and puzzles complementing the simple hidden object scenes. Like in most first-person point-and-click adventures, the player navigates through various locations by clicking on hotspots positioned over obvious exit openings, like doors and other places. The rooms are presented as a series of static screens with interactive portions. The cursor is context-sensitive, changing shape when hovering over an interactive part of the scenery. It morphs into an eye when over a place with a close-up view, that sometimes contains a hidden object scene or a mini-game. It transforms into golden arrows when over one of the exit hotspots. It becomes a hand when over a scenery object that can be collected. It displays swirling blue circles over special areas where an inventory item can be used.' FROM games WHERE igdb_id = 64723 ON CONFLICT (game_id, language_code) DO NOTHING;
