INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sushi Academy', 'Time management game. Old Sushi Master, runs a world-famous restaurant. His snacks are enjoyed by an array of fans who would love to know the secrets of sushi making. Under the Master''s guidance, learn to chop vegetables, cut fish and decorate and serve meals. Create more complicated dishes, and maybe you will surpass your master.' FROM games WHERE igdb_id = 47780 ON CONFLICT (game_id, language_code) DO NOTHING;
