INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ratchet & Clank Future: A Crack in Time', 'Ratchet & Clank Future: A Crack in Time (known as Ratchet & Clank: A Crack in Time in most PAL countries) is a platform game developed by Insomniac Games and published by Sony Computer Entertainment for the PlayStation 3 video game console. It is the sequel to Ratchet & Clank Future: Tools of Destruction and Ratchet & Clank Future: Quest for Booty. The game was released for the PlayStation 3 in North America on October 27, 2009, in Australia on November 5, 2009, and in Europe on November 6, 2009. A fourth installment, titled Ratchet & Clank: Into the Nexus, was released in November 2013 for the PlayStation 3.' FROM games WHERE igdb_id = 1795 ON CONFLICT (game_id, language_code) DO NOTHING;
