INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Webkinz Jr.', 'Webkinz Jr. was the preschool counterpart of Webkinz. It was intended to be a more educational site for a younger audience of children aged 3-6. The site launched in April 2009 and was ultimately shut down some time in 2018.' FROM games WHERE igdb_id = 318830 ON CONFLICT (game_id, language_code) DO NOTHING;
