INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('atv-quad-kings', 51012, '2009-09-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6c6i.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/krvpi1zq2rlfdnjomizp.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ATV: Quad Kings', 'ATV Quad Kings immerses the player in the world of ATV motocross racing where aggressive driving and hard-hitting skills are needed to become the King of ATVs. Travel across the globe from the United States to Australia and race in nine breathtaking locations. Compete in incredible high-adrenaline races at each track… but that’s not all! Perform tricks and catch big air in freestyle events to increase your skill rating. There’s no where to hide! It’s fast and furious four-wheel racing on Wii! Features • Four championship levels from Amateur to All Star gets everyone in the game • Four game modes: World Tour, Arcade, Time Trial, and Freestyle • Many quad bikes and dune buggy vehicles to choose from, each with varying suspension, acceleration, speed, handling, and braking attributes • Earn money from races to customize your vehicles in your virtual garage • Race head-to-head in two player Arcade and Freestyle events • Win the five World Tour trophies including the ultimate ATV Quad Kings Trophy to be #1 • Master the Freestyle stunt events to unlock tracks in the Arcade game mode • Contend with different road surfaces such as soil, grass, and water—and watch out for the occasion rain shower to change the track conditions • Play with your Wii Wheel for additional fun' FROM games WHERE igdb_id = 51012 ON CONFLICT (game_id, language_code) DO NOTHING;
