INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tears to Tiara Gaiden: Avalon no Nazo', 'Similar to the previous work "Tears to Tiara: The Land of the Flower Crown", it is an "adventure + simulation RPG" that follows the fantasy world view and repeats the adventure part and the turn-based battle part to advance the story. It is also positioned as a gaiden work, and the battle system has been changed and added according to the original story.' FROM games WHERE igdb_id = 76907 ON CONFLICT (game_id, language_code) DO NOTHING;
