INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('animal-kingdom-wildlife-expedition', 51010, '2009-09-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9pov.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sfn6iqxz9y94qqw9u2ux.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Animal Kingdom: Wildlife Expedition', 'A Fantastic Photo Safari! Nestled in the middle of remote Animal Island is a secret preserve where the most rare, exotic and reclusive wild animals roam. Only the best wildlife photographers gain access to this area, so you need to impress your editor with good work and earn the trust of the furry and feathered inhabitants! Features • Explore jungles, savannahs and other wild environments! Pull up your binoculars to find movement or other signs of animal activity from your rugged 4x4! • Getting the best shots means moving close to the wildlife! To do that you need to walk slowly among the herds, and even wear innovative animal disguises! • Sort through your best shots back at Base Camp and save them in your Album, or submit your freelance work to editors who judge your images for publication!' FROM games WHERE igdb_id = 51010 ON CONFLICT (game_id, language_code) DO NOTHING;
