INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rescue at Rajini Island', 'Embark on an epic adventure into the unknown as you search for Captain Walsh and his missing crew of adventurers; lost on an uncharted Island. Explore ancient ruins and search for evidence of a lost civilization. Gather diary entries from the crew and un-scramble foreign symbols and engravings as you follow a path of clues...but toward what answer? Find out for yourself in this exciting Hidden Object masterpiece!  Engaging game-play.  Beautiful Hidden Object scenes.  Explore the unknown!' FROM games WHERE igdb_id = 54317 ON CONFLICT (game_id, language_code) DO NOTHING;
