INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '3 on 3 NHL Arcade', '3 on 3 NHL Arcade is an NHL-licensed arcade-style hockey sports game for the Xbox 360 and PlayStation 3, using the NHL 09 engine. The game was developed by NHL 09''s EA Canada under the EA Sports Freestyle banner. A demo for the game is available on the PlayStation 3 version of NHL 11 and NHL 12. For NHL 13, there is a code to unlock the whole game.' FROM games WHERE igdb_id = 21258 ON CONFLICT (game_id, language_code) DO NOTHING;
