INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'N.O.V.A.: Near Orbit Vanguard Alliance', 'With Earth no longer able to sustain life, huge artificial satellites called ''near-orbitals'' were constructed for people to live on. To protect themselves, the near-orbitals banded together to form N.O.V.A., the Near Orbit Vanguard Alliance. Against his will, retired marine hero Kal Wardin is forcefully returned to active duty to prevent mankind''s annihilation.' FROM games WHERE igdb_id = 19316 ON CONFLICT (game_id, language_code) DO NOTHING;
