INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Delicious: Emily''s Holiday Season', 'Deck the halls with love and joy in Delicious: Emily''s Holiday Season, a wonderful time management sequel to warm up your holidays! It''s winter in Snuggford and Emily is preparing for her family''s holiday party at a cozy little lodge. Soon, romance fills the air as two suitors vie for Emily''s attention. Whom will she choose? Join Emily in this romantic new adventure through a winter wonderland! Meet her family and catch up with friends. Help and serve guests delicious holiday treats. Take part in jolly activities and find out who the lucky guy will be in Delicious: Emily''s Holiday Season!' FROM games WHERE igdb_id = 89536 ON CONFLICT (game_id, language_code) DO NOTHING;
