INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LEGO Indiana Jones 2: The Adventure Continues', 'LEGO Indy is back in his biggest adventure yet. Battle through all four movies, including all-new levels from the original adventures and your favorite new moments from The Kingdom of the Crystal Skull... or in true LEGO fashion, get creative and build your own levels to play with friends! New modes including two-player drop-in, drop-out split-screen gameplay lets you play together with your friends and family like never before.' FROM games WHERE igdb_id = 138 ON CONFLICT (game_id, language_code) DO NOTHING;
