INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('time-gentlemen-please', 6253, '2009-07-02', 90, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4h7c.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arubc.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Time Gentlemen, Please!', 'Ben There, Dan That! and Time Gentlemen, Please! are a couple of rip-roaring point-and-click adventure games . With tongue firmly in cheek, sit back, relax, and put your mind to work solving puzzles, and reading some very funny dialogue. It''s like a book, only good! From an horrific and untimely death in deep, dark Peru, via preposterous-and-suspect alien invasions, to whipping back-and-forth in time to stop Hitler and his army of robot Nazi dinosaur clones, this is one set of adventures you''re unlikely to forget. Key features: Funny words that''ll actually probably make you laugh out loud! Graphics AND sound effects! Thousands of unique responses for almost every action you can think of! NAZI DINOSAURS!' FROM games WHERE igdb_id = 6253 ON CONFLICT (game_id, language_code) DO NOTHING;
